/* Library v77: the 76 supplements from Supplements v22 data, shaped as Library entries (kind supp) so they sit in the same Library under the Supplements switch. Built from /supplements/v22/data.js on 28 Oct 2026; the Supplements page keeps the full read. */
window.BS_DATA=window.BS_DATA.concat([{"slug":"s-vitamin-c","sid":"vitamin-c","name":"Vitamin C","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1000,"alias":"ascorbic acid","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Repair","mid":"Skin","lt":"Immunity","lb":"Protection"},"dots":[]},"canva":false,"primary":"Repair","roles":["Repair","Skin","Immunity","Protection"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"250 mg-1 g/day","freq":"1-2x daily, split","cycle":"","route":"Oral, IV","half":"","use":"Collagen cofactor; regular intake trims cold length a little and halves colds under heavy physical stress","conf":"reported"},"desc":{},"syn":["FOXO4-DRI","Glutathione","Cerebrolysin","BPC-157","TB-500","GHK-Cu","KPV","LL-37","Collagen Peptides","Thymosin Alpha-1","Thymalin","Crystagen"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Collagen cofactor; regular intake trims cold length a little and halves colds under heavy physical stress","kw":["Foundations","ascorbic acid"],"whoNot":[{"t":"People with G6PD deficiency (IV or megadoses)","why":"High-dose IV vitamin C can burst red blood cells in G6PD deficiency.","conf":"verified"},{"t":"People with hemochromatosis or iron overload","why":"Vitamin C raises iron absorption from food.","conf":"verified"},{"t":"People with a history of oxalate kidney stones","why":"Some vitamin C is converted to oxalate; 1 g/day raises urine oxalate.","conf":"verified"},{"t":"People using fingerstick glucose meters after IV doses","why":"High blood vitamin C can falsely raise some meter readings.","conf":"reported"}],"kind":"supp","supp":{"cat":"Foundations","does":"Cofactor for collagen synthesis, so the GHK-Cu and BPC-157 repair work depends on it. Also used as an antioxidant buffer during senolytic clearance and for immune cell and NK cell function.","benefits":"Corrects and prevents deficiency (scurvy), and is required to build collagen. Regular intake of 200 mg or more a day shortens colds by about 8% in adults and 14% in children, and cut cold incidence by about half in marathon runners, skiers and soldiers under heavy physical or cold stress. It does not prevent colds in the general population, and starting it once symptoms begin does little. Oral doses do not treat cancer; high plasma levels need IV dosing.","ev":"Moderate","evwhy":"Cochrane review of regular supplementation for colds (summarised by NIH ODS); plasma saturation data at 200-400 mg/day","warn":["Above 2 g/day: diarrhoea, nausea and cramps from unabsorbed vitamin C.","Kidney stone formers: supplements raise urinary oxalate; LPI suggests avoiding 1 g/day or more.","Hemochromatosis or iron overload: high doses raise iron absorption."],"buy":["Label should read 250-1,000 mg vitamin C (as ascorbic acid) per serving; more than 1 g per dose mostly ends in the urine.","Buffered forms: check the sodium or calcium per serving if you limit either."],"dn":"2g/day is the phase-wide figure in Phases 0, 1 and 7. Take 1g with oral collagen.","appr":"FDA-approved as: Ascorbic acid injection, Rx, IV, short-term treatment of scurvy when oral is not possible","routes":[{"r":"Oral","note":"Absorption falls as the dose rises; above about 1 g much of it is lost in urine or stays in the gut and loosens stools."},{"r":"IV","note":"Clinical only. Used in oncology and critical-care trials because only IV reaches pharmacological plasma levels; screen for G6PD deficiency first (hemolysis risk)."}]}},{"slug":"s-vitamin-d3-and-k2","sid":"vitamin-d3-and-k2","name":"Vitamin D3 and K2","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1001,"alias":"D3, K2, MK-7, cholecalciferol, vitamin D","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Immunity","mid":"DNA","lt":"Endocrine","lb":"Inflammation"},"dots":[]},"canva":false,"primary":"Immunity","roles":["Immunity","DNA","Endocrine","Inflammation"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"D3 1,000-2,000 IU + K2","freq":"daily, with fat","cycle":"","route":"Oral, IM","half":"","use":"D3 corrects deficiency for bone and muscle; K2 MK-7 activates bone proteins; little benefit in replete healthy adults","conf":"reported"},"desc":{},"syn":["Glutathione","TB-500","Epithalon","Pinealon","N-Acetyl Epithalon Amidate","Ipamorelin","CJC-1295 no DAC","Tesamorelin","Sermorelin","GHRP-2","Hexarelin","HGH"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"D3 corrects deficiency for bone and muscle; K2 MK-7 activates bone proteins; little benefit in replete healthy adults","kw":["Foundations","D3","K2","MK-7","cholecalciferol","vitamin D"],"whoNot":[{"t":"People on warfarin","why":"K2 as low as 10 to 20 mcg a day can undo warfarin and shift INR.","conf":"verified"},{"t":"People with sarcoidosis or granulomatous disease","why":"These tissues activate vitamin D themselves, driving calcium too high.","conf":"verified"},{"t":"People on thiazide diuretics","why":"Thiazides hold on to calcium; added D can tip into hypercalcaemia.","conf":"verified"},{"t":"People on digoxin","why":"High calcium from excess D raises the risk of digoxin heart rhythm toxicity.","conf":"reported"}],"kind":"supp","supp":{"cat":"Foundations","does":"Immune modulator that T-cell activation depends on. The protocol also ties D3 status to telomere length and hormonal support. K2 (MK-7) is added in the TB-500 stack for inflammation modulation.","benefits":"D3 treats and prevents deficiency, rickets and osteomalacia; with calcium it modestly cut fractures (about 6% any fracture, 16% hip) in older adults. In VITAL (2,000 IU/day, 25,871 adults, 5.3 years) it did not cut cancer, heart attacks, strokes, fractures or depression in mostly replete people. The Endocrine Society (2024) backs above-RDA intake only for ages 1-18, pregnancy, prediabetes and 75+. K2 (MK-7) lowers undercarboxylated osteocalcin and one 3-year trial at 180 mcg/day slowed bone strength loss; it has no proven effect on arterial calcification in humans.","ev":"Moderate","evwhy":"D3: VITAL, USPSTF on falls, Endocrine Society 2024. K2: a few small trials with mixed bone results (Limited).","warn":["Too much D causes high calcium: nausea, weakness, kidney stones, arrhythmia; blood 25(OH)D above 50 ng/mL (125 nmol/L) is linked to harm.","Warfarin and other vitamin K antagonists: MK-7 as low as 10-20 mcg/day can destabilise INR. Avoid K2 unless the prescriber adjusts.","Granulomatous disease (sarcoidosis), some lymphomas and primary hyperparathyroidism raise calcium with vitamin D."],"buy":["Check IU and mcg on the label (1 mcg = 40 IU); 5,000 IU products exceed the 4,000 IU UL.","K2 should say MK-7 (menaquinone-7) with the mcg amount; MK-4 products are dosed in mg and are a different form."],"dn":"With 200mcg MK-7 per day in the TB-500 stack. With Thymosin Alpha-1 the protocol targets a blood level above 40 ng/mL.","appr":"Cholecalciferol is FDA-approved only inside a combination osteoporosis tablet; K2 (MK-7) is not approved anywhere.","routes":[{"r":"Oral","note":"Both are fat-soluble: take with the largest meal containing fat."},{"r":"IM","note":"Clinical only, for malabsorption; large intermittent boluses are not preferred for routine use."},{"r":"Skin (UVB)","note":"Sun makes D3; output falls with latitude, winter, darker skin, sunscreen and age."}]}},{"slug":"s-zinc","sid":"zinc","name":"Zinc","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1002,"alias":"zinc picolinate","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Repair","mid":"Immunity","lt":"DNA","lb":"Endocrine"},"dots":[]},"canva":false,"primary":"Repair","roles":["Repair","Immunity","DNA","Endocrine"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"8-25 mg/day","freq":"daily, with food","cycle":"","route":"Oral, Lozenge","half":"","use":"Immune and wound-healing mineral; lozenges cut cold length about 2 days; long-term high doses drain copper","conf":"reported"},"desc":{},"syn":["Glutathione","BPC-157","TB-500","GHK-Cu","KPV","LL-37","Collagen Peptides","Epithalon","Pinealon","N-Acetyl Epithalon Amidate","Ipamorelin","CJC-1295 no DAC"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Immune and wound-healing mineral; lozenges cut cold length about 2 days; long-term high doses drain copper","kw":["Foundations","zinc picolinate"],"whoNot":[{"t":"Long-term high-dose users, especially with zinc denture cream","why":"Excess zinc blocks copper, causing anaemia and nerve damage that can be permanent.","conf":"verified"},{"t":"Anyone considering zinc nasal sprays or gels","why":"Linked to permanent loss of smell; FDA warned in 2009.","conf":"verified"},{"t":"People on quinolone or tetracycline antibiotics","why":"Zinc binds these antibiotics in the gut and cuts their absorption.","conf":"verified"},{"t":"People after bariatric surgery","why":"Already prone to copper deficiency; zinc pushes copper lower.","conf":"reported"}],"kind":"supp","supp":{"cat":"Foundations","does":"Wound healing cofactor and the balance to the copper in GHK-Cu. Also listed as a telomerase cofactor, a T-cell and thymulin cofactor, and for hormone support.","benefits":"Corrects deficiency, which impairs immunity, wound healing, taste and growth. Zinc lozenges started within 24 hours shorten colds by roughly 2 days (Cochrane 2024, low certainty) but do little for severity or prevention. In AREDS, 80 mg zinc plus antioxidants and 2 mg copper cut progression to advanced macular degeneration by 25% in high-risk people. It does not boost immunity or testosterone above normal in people who are already replete.","ev":"Moderate","evwhy":"Cochrane 2024 (cold duration, low certainty); AREDS and AREDS2 for macular degeneration","warn":["Copper depletion: long-term intake above about 40 mg/day, and 50 mg or more for weeks, inhibits copper absorption; can cause anemia, low white cells and nerve damage.","At 50 mg+ for weeks: lower HDL cholesterol and reduced immune function.","Nausea, vomiting and metallic taste, especially on an empty stomach."],"buy":["Label must state elemental zinc in mg; compound weight (for example 100 mg zinc gluconate) is far less zinc.","For daily use above 25 mg, choose a product with 1-2 mg copper per serving."],"dn":"15-30mg with BPC-157. 30-50mg with GHK-Cu, as zinc picolinate.","appr":"FDA-approved as: Zinc sulfate injection, Rx, IV additive for parenteral nutrition; zinc acetate capsules, Rx, oral, Wilson's disease maintenance","routes":[{"r":"Oral","note":"Take with food if it causes nausea; separate from iron doses of 25 mg or more."},{"r":"Lozenge","note":"Dissolve slowly in the mouth; works only at the start of a cold."},{"r":"Nasal","note":"Avoid: zinc nasal gels and sprays have caused loss of smell that may be permanent."}]}},{"slug":"s-magnesium-glycinate","sid":"magnesium-glycinate","name":"Magnesium Glycinate","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1003,"alias":"magnesium","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Sleep","mid":"Endocrine","lt":"Heart","lb":"Heart"},"dots":[]},"canva":false,"primary":"Sleep","roles":["Sleep","Endocrine","Heart"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"200-350 mg elemental/day","freq":"daily, evening","cycle":"","route":"Oral, IV/IM","half":"","use":"Most people under-eat magnesium; modest help for blood pressure, migraine prevention and mild poor sleep","conf":"reported"},"desc":{},"syn":["FOXO4-DRI","BPC-157","TB-500","GHK-Cu","KPV","LL-37","Collagen Peptides","Pinealon","Ipamorelin","CJC-1295 no DAC","Tesamorelin","Sermorelin"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Most people under-eat magnesium; modest help for blood pressure, migraine prevention and mild poor sleep","kw":["Foundations","magnesium"],"whoNot":[{"t":"People with reduced kidney function","why":"Kidneys clear magnesium; build-up causes low blood pressure and weakness.","conf":"verified"},{"t":"People on bisphosphonates, quinolones or tetracyclines","why":"Magnesium binds them; doses need spacing by hours.","conf":"verified"},{"t":"People with myasthenia gravis","why":"Magnesium reduces acetylcholine release at the muscle and can worsen weakness.","conf":"reported"}],"kind":"supp","supp":{"cat":"Foundations","does":"Co-signal for GH release, needed for actin polymerization with TB-500, and taken before bed for sleep. Also listed for cardiac rhythm support.","benefits":"Corrects low intake, common in older adults and people on PPIs or diuretics. Supplements lower blood pressure a little, most in people with uncontrolled hypertension (240 mg/day or more). Neurology societies rate it probably effective for migraine prevention at doses above the UL. A 2025 trial of 250 mg magnesium bisglycinate gave a small improvement in insomnia scores; it is not a sedative. Evidence for diabetes control, bone and athletic performance is weak.","ev":"Moderate","evwhy":"2021 meta-analysis of 49 RCTs on blood pressure; AAN/AHS migraine rating; one 2025 RCT for sleep (small effect)","warn":["Diarrhoea, nausea and cramps above the UL, worst with oxide, citrate and chloride.","Kidney disease: magnesium can accumulate to toxic levels; avoid without medical advice.","Toxicity (low blood pressure, weakness, irregular heartbeat) mostly with laxatives or antacids over 5,000 mg/day."],"buy":["Read elemental magnesium per serving, not the compound weight (1,000 mg glycinate gives roughly 140 mg magnesium).","'Buffered' glycinate often contains oxide; look for 'fully reacted' or a single-form label."],"dn":"Before bed for sleep and GH. Magnesium L-Threonate is its own entry, for brain use.","appr":"FDA-approved as: Magnesium sulfate injection, Rx (pre-eclampsia/eclampsia seizures, hypomagnesemia); magnesium hydroxide/oxide also OTC antacid monograph","routes":[{"r":"Oral","note":"30-40% of dietary magnesium is absorbed; smaller split doses absorb better and cause less diarrhoea."},{"r":"IV/IM","note":"Clinical only, hospital use with monitoring."},{"r":"Topical (oils, Epsom baths)","note":"Skin absorption is poorly shown; do not count it toward intake."}]}},{"slug":"s-omega-3-epa-and-dha","sid":"omega-3-epa-and-dha","name":"Omega-3 (EPA and DHA)","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1004,"alias":"fish oil, DHA, EPA","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Inflammation","mid":"Cognition","lt":"Heart","lb":"Heart"},"dots":[]},"canva":false,"primary":"Inflammation","roles":["Inflammation","Cognition","Heart"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"250 mg-1 g EPA+DHA/day","freq":"daily, with a meal","cycle":"","route":"Oral, IV","half":"","use":"Lowers triglycerides at 2-4 g; DHA in pregnancy cuts preterm birth; heart benefit mixed and AFib risk rises with dose","conf":"reported"},"desc":{},"syn":["Cerebrolysin","BPC-157","TB-500","GHK-Cu","KPV","LL-37","Collagen Peptides","SS-31","Epithalon","Pinealon","N-Acetyl Epithalon Amidate","Hexarelin"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Lowers triglycerides at 2-4 g; DHA in pregnancy cuts preterm birth; heart benefit mixed and AFib risk rises with dose","kw":["Foundations","fish oil","DHA","EPA"],"whoNot":[{"t":"People with past or current atrial fibrillation","why":"Over 1 g a day raised AF risk in trials pooled in a 2021 meta-analysis.","conf":"reported"},{"t":"People on blood thinners before surgery","why":"High doses add to bleeding tendency.","conf":"reported"},{"t":"People on blood pressure drugs with low pressure","why":"Omega-3s lower blood pressure slightly; effects add up.","conf":"reported"}],"kind":"supp","supp":{"cat":"Foundations","does":"Membrane material and anti-inflammatory support. DHA goes to brain and synaptic membranes and to cardiolipin in mitochondria. Also listed for telomere preservation.","benefits":"At 4 g/day, prescription omega-3s lower triglycerides, and purified EPA at 4 g/day cut cardiovascular events by 25% in high-risk statin users (REDUCE-IT); a mixed EPA+DHA product at the same dose did not (STRENGTH). In healthy adults, 1 g/day (VITAL) did not cut major cardiovascular events. In pregnancy, long-chain omega-3s cut preterm birth by 11% and early preterm birth by 42% (Cochrane 2018). It does not reliably improve mood, cognition or joint pain in people without deficiency.","ev":"Strong","evwhy":"Strong for triglycerides and preterm birth (Cochrane 2018); mixed for heart events (REDUCE-IT vs STRENGTH, VITAL)","warn":["Atrial fibrillation: meta-analysis of 7 trials, HR 1.25 overall and 1.49 at more than 1 g/day, in people with or at risk of heart disease.","Bleeding: antiplatelet effect at high doses; stop before surgery if your surgeon asks.","Fishy burps, heartburn, nausea and loose stools are common."],"buy":["Read EPA and DHA mg per serving, not 'fish oil 1,000 mg' (typical: 180 EPA + 120 DHA).","Look for oxidation testing (low peroxide and anisidine values) or a third-party seal; rancid oil smells fishy."],"dn":"1-2g of DHA for the brain and mitochondrial uses (Semax, SS-31, PE-22-28, Cortagen).","appr":"FDA-approved as: Omega-3-acid ethyl esters capsules (EPA+DHA) and icosapent ethyl capsules (EPA), Rx, severe hypertriglyceridemia","routes":[{"r":"Oral","note":"Take with a fat-containing meal; ethyl esters need fat to absorb."},{"r":"IV","note":"Clinical only, as part of hospital parenteral nutrition."}]}},{"slug":"s-vitamin-e","sid":"vitamin-e","name":"Vitamin E","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1005,"alias":"tocopherol, tocotrienol","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Protection","mid":"Energy","lt":"Energy","lb":"Energy"},"dots":[]},"canva":false,"primary":"Protection","roles":["Protection","Energy"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"15 mg (22 IU) from food","freq":"daily","cycle":"","route":"Oral, Topical","half":"","use":"Fat-soluble antioxidant; deficiency is rare; high-dose pills failed for heart and cancer and raised prostate cancer","conf":"reported"},"desc":{},"syn":["GHK-Cu","SS-31","GHK-Cu + BPC-157","GHK-Cu + KPV","GLOW","KLOW"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Fat-soluble antioxidant; deficiency is rare; high-dose pills failed for heart and cancer and raised prostate cancer","kw":["Foundations","tocopherol","tocotrienol"],"whoNot":[{"t":"Men concerned about prostate cancer","why":"In the SELECT trial, 400 IU a day raised prostate cancer risk 17%.","conf":"verified"},{"t":"People on warfarin or antiplatelets","why":"Vitamin E reduces platelet clumping and raises bleeding risk.","conf":"verified"},{"t":"People with a history of haemorrhagic stroke","why":"Meta-analysis linked vitamin E to more bleeding strokes.","conf":"reported"},{"t":"People taking statins with niacin for HDL","why":"Antioxidant combinations blunted the HDL rise.","conf":"reported"}],"kind":"supp","supp":{"cat":"Foundations","does":"Lipid-soluble antioxidant. Partner for GHK-Cu, and protects mitochondrial membranes with SS-31.","benefits":"Deficiency is rare outside fat-malabsorption disorders. At 800 IU/day natural form it improved liver histology in non-diabetic adults with fatty liver disease (PIVENS), a supervised use. It is part of the AREDS formula for macular degeneration. Large trials found no protection against heart attack, stroke or cancer; in SELECT, 400 IU/day raised prostate cancer risk by 17%, and HOPE-TOO saw more heart failure.","ev":"Limited","evwhy":"SELECT and HOPE-TOO show no benefit and some harm; PIVENS supports a narrow liver use","warn":["Men: avoid long-term high doses; SELECT showed 17% more prostate cancer, and 111% more high-grade cancer in men with low baseline selenium.","Bleeding and hemorrhagic stroke signals at high doses, especially with aspirin.","Heart failure: HOPE-TOO found 13% more heart failure on 400 IU/day."],"buy":["'d-' on the label means natural; 'dl-' means synthetic. Convert IU to mg before comparing.","Mixed tocopherol products should list each tocopherol in mg."],"dn":"Mixed tocopherols and tocotrienols with SS-31.","appr":"FDA-approved only as one ingredient of an IV multivitamin.","routes":[{"r":"Oral","note":"Needs dietary fat; take with a meal."},{"r":"Topical","note":"Common in skin products; contact dermatitis is reported and wound-scar benefit is not shown."}]}},{"slug":"s-b-complex-methylated","sid":"b-complex-methylated","name":"B-Complex (methylated)","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1006,"alias":"B vitamins, B12, methylated B","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Energy","mid":"Plasticity","lt":"Plasticity","lb":"Plasticity"},"dots":[]},"canva":false,"primary":"Energy","roles":["Energy","Plasticity"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"1 capsule, near RDA levels","freq":"daily, morning","cycle":"","route":"Oral, Sublingual","half":"","use":"Covers B12 and folate gaps for vegans, 50+, metformin and PPI users; B6 eases pregnancy nausea; no energy boost","conf":"reported"},"desc":{},"syn":["Cerebrolysin","NAD+","MOTS-C","SS-31","SLU-PP-332","AICAR","Retatrutide","Tirzepatide","Semaglutide","5-Amino-1MQ","L-Carnitine injectable","Lipo-C"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Covers B12 and folate gaps for vegans, 50+, metformin and PPI users; B6 eases pregnancy nausea; no energy boost","kw":["Foundations","B vitamins","B12","methylated B"],"whoNot":[{"t":"Anyone due for thyroid, troponin or hormone tests","why":"Biotin in B-complexes skews many lab tests; FDA linked it to a missed heart attack.","conf":"verified"},{"t":"People already taking B6 from other products","why":"B6 nerve damage has been reported at doses far below the old upper limit.","conf":"verified"},{"t":"People with gout or diabetes (niacin-containing)","why":"Niacin raises uric acid and blood glucose.","conf":"verified"},{"t":"People on levodopa without carbidopa","why":"B6 speeds levodopa breakdown and blunts it.","conf":"verified"}],"kind":"supp","supp":{"cat":"Foundations","does":"Methylated B vitamins. Used for neurotrophin signaling with Cerebrolysin, and listed with Semax and Cortagen and in the Phase 2 and Phase 5 stacks.","benefits":"Prevents and treats deficiency: B12 in vegans, adults over 50 and people on metformin or acid blockers; folate before and in early pregnancy. B6 at 10-25 mg 3-4 times a day is ACOG first-line for pregnancy nausea. B vitamins do not raise energy, endurance or cognition in people who are not deficient, even though they lower homocysteine.","ev":"Moderate","evwhy":"Strong for deficiency correction (ODS, USPSTF folic acid); RCTs show no cognitive or energy gain in replete adults","warn":["B6 neuropathy: tingling, burning or numbness; TGA reports cases below 50 mg/day and requires a warning above 10 mg/day.","Folic acid at high dose can mask B12 deficiency anaemia while nerve damage progresses; test B12 first in older adults.","Biotin interferes with many lab immunoassays (thyroid, troponin)."],"buy":["B6 per serving ideally 10 mg or less unless treating pregnancy nausea; check every product you take for B6.","Folate should show mcg DFE; folic acid counts toward the 1,000 mcg UL."],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Only about 1.3% of a 1,000 mcg B12 dose is absorbed, enough to correct most deficiency."},{"r":"Sublingual","note":"No better than swallowing for B12."},{"r":"Nasal (B12)","note":"Prescription gel raises blood B12; absorption about 2%."},{"r":"IM (B12)","note":"Clinical, for pernicious anemia, severe deficiency or neurological symptoms."}]}},{"slug":"s-selenium","sid":"selenium","name":"Selenium","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1007,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Protection","mid":"Immunity","lt":"Immunity","lb":"Immunity"},"dots":[]},"canva":false,"primary":"Protection","roles":["Protection","Immunity"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"55-100 mcg/day","freq":"daily","cycle":"","route":"Oral","half":"","use":"Antioxidant enzyme and thyroid mineral with a narrow window; may lower thyroid antibodies, excess linked to diabetes","conf":"reported"},"desc":{},"syn":["Glutathione","Thymosin Alpha-1","Thymalin"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Antioxidant enzyme and thyroid mineral with a narrow window; may lower thyroid antibodies, excess linked to diabetes","kw":["Foundations"],"whoNot":[{"t":"People already high in selenium (Brazil nuts)","why":"Topping up raised type 2 diabetes risk in trials.","conf":"verified"},{"t":"Men with high baseline selenium and prostate concerns","why":"SELECT follow-up: extra selenium raised high-grade prostate cancer in this group.","conf":"verified"},{"t":"People taking several multi-ingredient products","why":"Toxicity (hair and nail loss, garlic breath) from stacking.","conf":"verified"}],"kind":"supp","supp":{"cat":"Foundations","does":"Cofactor for glutathione peroxidase.","benefits":"Corrects deficiency, which is rare outside low-selenium soil regions. In autoimmune thyroiditis on levothyroxine, 200 mcg/day lowers thyroid peroxidase antibodies, but has not been shown to improve symptoms or reduce the drug dose. It does not prevent prostate, skin or other cancers: SELECT (200 mcg/day) found no benefit, and men with high baseline selenium had more high-grade prostate cancer.","ev":"Limited","evwhy":"SELECT and NPC null for cancer with harm signals; Cochrane thyroid review shows antibody drop only","warn":["Narrow window: garlic breath and metallic taste come first; hair loss and brittle nails signal selenosis.","Type 2 diabetes: NPC (200 mcg/day) raised risk, most in people with high baseline selenium; SELECT showed a non-significant rise.","Men with high selenium status: SELECT linked supplements to 91% more high-grade prostate cancer."],"buy":["Label should show mcg of elemental selenium; 50-100 mcg covers most people with a mixed diet.","Add up selenium in multivitamins, thyroid blends and protein powders."],"dn":"","appr":"FDA-approved as: Selenious acid injection, Rx, IV additive for parenteral nutrition","routes":[{"r":"Oral","note":"Organic forms absorb about 90%; take with food."}]}},{"slug":"s-folic-acid","sid":"folic-acid","name":"Folic Acid","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1008,"alias":"Folate, Vitamin B9, Pteroylmonoglutamic acid, Prenatal folic acid","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Reproductive","mid":"DNA","lt":"Heart","lb":"Heart"},"dots":[]},"canva":false,"primary":"Reproductive","roles":["Reproductive","DNA","Heart"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"400-800 mcg/day","freq":"Once daily","cycle":"","route":"Oral, IV/IM","half":"","use":"USPSTF Grade A: prevents neural tube defects when taken before and in early pregnancy","conf":"reported"},"desc":{},"syn":[],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"USPSTF Grade A: prevents neural tube defects when taken before and in early pregnancy","kw":["Foundations","Folate","Vitamin B9","Pteroylmonoglutamic acid","Prenatal folic acid"],"whoNot":[{"t":"Vegans, older adults and long-term metformin users","why":"Folic acid can hide B12 deficiency while nerve damage continues.","conf":"verified"},{"t":"People on methotrexate for cancer","why":"Folic acid can counter methotrexate.","conf":"verified"},{"t":"People on phenytoin or other anti-seizure drugs","why":"Folic acid can lower drug levels and trigger seizures.","conf":"verified"},{"t":"People with a history of colorectal polyps","why":"One trial found more advanced adenomas with 1 mg a day.","conf":"reported"}],"kind":"supp","supp":{"cat":"Foundations","does":"Synthetic folate used in every neural tube defect prevention trial and in flour fortification. Taken daily from at least a month before conception, it cuts the risk of spina bifida and anencephaly. Outside pregnancy planning it mainly corrects folate deficiency.","benefits":"Strongest evidence of any supplement for one outcome: daily folic acid before conception and through the first 2 to 3 months of pregnancy prevents neural tube defects (USPSTF 2023, Grade A). Canada saw a 46% fall in NTDs after mandatory flour fortification. It also treats folate deficiency anaemia. It does not boost energy or prevent heart attacks in people who already eat fortified food.","ev":"Strong","evwhy":"USPSTF 2023 Grade A recommendation; decades of RCT and fortification data for NTD prevention","warn":["Can correct the anaemia of B12 deficiency while nerve damage progresses; check B12 in older adults, vegans and metformin users before high doses","Doses above 1,000 mcg only under medical supervision (prior NTD pregnancy, certain drugs)","Unmetabolised folic acid appears in blood above about 300-400 mcg single doses; clinical meaning unclear"],"buy":["Check the label in mcg folic acid and mcg DFE: 400 mcg folic acid reads as 667 mcg DFE","Count fortified cereal and other supplements toward the 1,000 mcg folic acid UL"],"dn":"","appr":"FDA-approved as: Folic acid 1 mg tablets, Rx, megaloblastic and nutritional anaemias","routes":[{"r":"Oral","note":"Standard; tablets or within prenatal multivitamins"},{"r":"IV/IM","note":"Clinical only, for malabsorption or when oral is not possible"}]}},{"slug":"s-iron","sid":"iron","name":"Iron","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1009,"alias":"Ferrous sulfate, Ferrous bisglycinate, Iron bisglycinate, Ferrous fumarate, Ferrous gluconate, Ferritin","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Energy","mid":"Cognition","lt":"Reproductive","lb":"Hair"},"dots":[]},"canva":false,"primary":"Energy","roles":["Energy","Cognition","Reproductive","Hair","Drive"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"40-65 mg elemental","freq":"Alternate days","cycle":"","route":"Oral, IV","half":"","use":"Corrects iron deficiency and anaemia: fatigue, focus, pregnancy needs. Only when ferritin is low","conf":"reported"},"desc":{},"syn":["Vitamin B12","MIC + B12"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Corrects iron deficiency and anaemia: fatigue, focus, pregnancy needs. Only when ferritin is low","kw":["Foundations","Ferrous sulfate","Ferrous bisglycinate","Iron bisglycinate","Ferrous fumarate","Ferrous gluconate","Ferritin"],"whoNot":[{"t":"People with thalassaemia trait","why":"Small red cells look like iron deficiency but are not; iron overloads them. Common in Southeast Asia.","conf":"reported"},{"t":"People with undiagnosed hemochromatosis","why":"Absorb too much iron and store it in liver and heart.","conf":"verified"},{"t":"People on levothyroxine, quinolones or tetracyclines","why":"Iron binds these drugs in the gut; take them hours apart.","conf":"verified"},{"t":"People in malaria areas without screening","why":"WHO: iron in malaria zones without screening raised harm.","conf":"verified"}],"kind":"supp","supp":{"cat":"Foundations","does":"Builds haemoglobin and myoglobin to carry oxygen. A supplement corrects iron deficiency and iron deficiency anaemia, common in menstruating women, pregnancy, vegans and endurance athletes. Without deficiency it adds risk, not benefit.","benefits":"Treats iron deficiency and iron deficiency anaemia, restoring haemoglobin, exercise capacity and, in deficient women, fatigue and cognition. Low ferritin hair shedding can improve once stores recover. WHO advises 30-60 mg daily in pregnancy; NICE and USPSTF do not endorse routine use. It does not raise energy in people with normal iron.","ev":"Strong","evwhy":"Strong for deficiency (ODS, WHO 2016); stable-isotope trials (Moretti 2015, Stoffel 2017, 2020) define dosing; no benefit if replete","warn":["Accidental iron overdose is a leading cause of fatal poisoning in children under 6","Men and postmenopausal women: avoid without proven deficiency (overload risk)","Haemochromatosis or other iron overload: avoid"],"buy":["Read elemental iron, not salt weight: 325 mg ferrous sulfate = 65 mg iron","Test ferritin and haemoglobin first and retest after 8-12 weeks"],"dn":"","appr":"FDA-approved as: Ferric maltol capsules, Rx, oral, iron deficiency anaemia; also IV iron products (iron sucrose, ferric carboxymaltose etc.)","routes":[{"r":"Oral","note":"First line; one dose every other morning absorbs best per dose"},{"r":"IV","note":"Clinical only: oral failure, malabsorption, late pregnancy, heavy ongoing loss"}]}},{"slug":"s-iodine","sid":"iodine","name":"Iodine","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1010,"alias":"Potassium iodide, Sodium iodide, KI, Kelp, Iodised salt","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Endocrine","mid":"Reproductive","lt":"Cognition","lb":"Cognition"},"dots":[]},"canva":false,"primary":"Endocrine","roles":["Endocrine","Reproductive","Cognition"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"150 mcg/day","freq":"Once daily","cycle":"","route":"Oral","half":"","use":"Thyroid hormone and fetal brain development; 150 mcg advised in pregnancy and breastfeeding","conf":"reported"},"desc":{},"syn":[],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Thyroid hormone and fetal brain development; 150 mcg advised in pregnancy and breastfeeding","kw":["Foundations","Potassium iodide","Sodium iodide","KI","Kelp","Iodised salt"],"whoNot":[{"t":"People with Hashimoto's or autoimmune thyroid disease","why":"Excess iodine can worsen thyroiditis and trigger hypothyroidism.","conf":"verified"},{"t":"People with nodular goitre","why":"Extra iodine can trigger hyperthyroidism (Jod-Basedow).","conf":"verified"},{"t":"People on amiodarone or lithium","why":"These already disturb thyroid function; iodine adds to it.","conf":"verified"},{"t":"People scheduled for radioactive iodine scans or treatment","why":"Extra iodine blocks uptake and spoils the test.","conf":"reported"}],"kind":"supp","supp":{"cat":"Foundations","does":"Needed to make thyroid hormone, which drives metabolism and fetal brain development. Pregnancy and breastfeeding raise needs sharply. Vegans and people who avoid dairy, seafood and iodised salt are most at risk of low intake.","benefits":"Prevents iodine deficiency, goitre and hypothyroidism. Mild deficiency in pregnancy is linked to lower child IQ, so the ATA and Australia's NHMRC advise a 150 mcg supplement when planning, pregnant or breastfeeding; the UK NHS does not routinely. It does not boost metabolism or weight loss in people with adequate intake, and excess can cause thyroid disease.","ev":"Strong","evwhy":"Strong at population level for deficiency and pregnancy (ATA, NHMRC 2010); individual RCT outcome data in mild deficiency are mixed","warn":["Autoimmune thyroid disease (Hashimoto's, Graves'): adverse effects possible at normal intakes; check with your thyroid doctor","Excess causes goitre, raised TSH, hypothyroidism, hyperthyroidism and thyroiditis","Iodine contrast scans and amiodarone deliver large iodine loads; tell clinicians if supplementing"],"buy":["Label should state mcg iodine and the source (potassium iodide), not just 'kelp'","150 mcg per daily serving is the target; avoid stacking with iodine-containing multis"],"dn":"","appr":"FDA-approved as: Potassium iodide tablets and oral solution, OTC, thyroid blocking in radiation emergencies","routes":[{"r":"Oral","note":"Potassium iodide tablets or within a prenatal multivitamin; iodised salt for diet"}]}},{"slug":"s-vitamin-b12","sid":"vitamin-b12","name":"Vitamin B12","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1011,"alias":"Cobalamin, Cyanocobalamin, Methylcobalamin, Hydroxocobalamin, Adenosylcobalamin","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Neuroprotection","mid":"Energy","lt":"Cognition","lb":"Mood"},"dots":[]},"canva":false,"primary":"Neuroprotection","roles":["Neuroprotection","Energy","Cognition","Mood"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"250-1,000 mcg/day","freq":"Once daily","cycle":"","route":"Oral, Sublingual","half":"","use":"Prevents and treats B12 deficiency: anaemia, nerve damage. Essential for vegans, 50+ and metformin users","conf":"reported"},"desc":{},"syn":[],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Prevents and treats B12 deficiency: anaemia, nerve damage. Essential for vegans, 50+ and metformin users","kw":["Foundations","Cobalamin","Cyanocobalamin","Methylcobalamin","Hydroxocobalamin","Adenosylcobalamin"],"whoNot":[{"t":"People with Leber's hereditary optic neuropathy","why":"Cyanocobalamin can speed optic nerve damage; use other forms.","conf":"verified"},{"t":"People with polycythaemia vera","why":"Treating B12 deficiency can unmask raised red cell counts.","conf":"verified"},{"t":"People prone to acne or rosacea","why":"High-dose B12 linked to acne flares.","conf":"reported"}],"kind":"supp","supp":{"cat":"Foundations","does":"Needed for red blood cells, myelin and DNA synthesis. Absorption falls with age, metformin and acid-reflux drugs, and plant foods contain none. High-dose oral B12 works for most people, even those with poor absorption.","benefits":"Prevents and treats B12 deficiency, which causes megaloblastic anaemia, neuropathy, memory problems and low mood. High-dose oral (1,000-2,000 mcg) normalised levels as well as injections in a Cochrane review. Essential for vegans, and advised for adults over 50 from fortified foods or supplements. It does not raise energy or cognition in people with normal B12.","ev":"Strong","evwhy":"Strong for deficiency in at-risk groups (IOM via ODS); Cochrane 2018 oral vs IM, 3 small RCTs, low certainty","warn":["High folic acid can hide B12 deficiency anaemia while nerve damage progresses","Pernicious anaemia with neurological symptoms needs injections first, not a supplement trial","Recent high-dose use inflates serum B12 tests; test MMA or stop 1-2 weeks before if checking status"],"buy":["Check mcg per serving; 1,000 mcg tablets are cheap and sufficient for deficiency","Vegans: cyanocobalamin is stable in light and heat"],"dn":"","appr":"FDA-approved as: Cyanocobalamin injection, Rx, IM/SC, B12 deficiency incl. pernicious anaemia","routes":[{"r":"Oral","note":"High doses absorb about 1-2% by passive diffusion, enough without intrinsic factor"},{"r":"Sublingual","note":"No better than swallowed oral"},{"r":"IM","note":"Clinical only; standard for pernicious anaemia with neurological signs"},{"r":"Nasal","note":"Prescription gel; about 2% bioavailable, similar to oral"}]}},{"slug":"s-quercetin","sid":"quercetin","name":"Quercetin","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1012,"alias":"senolytic, flavonoid","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Aging","mid":"Aging","lt":"Aging","lb":"Aging"},"dots":[]},"canva":false,"primary":"Aging","roles":["Aging"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"500 mg-1 g/day","freq":"1-2x daily, with food","cycle":"","route":"Oral, IV","half":"","use":"Onion and apple flavonoid; the Q in dasatinib+quercetin senolytic trials; small blood pressure drop at 500 mg+/day","conf":"reported"},"desc":{},"syn":["FOXO4-DRI","Glutathione","Cerebrolysin"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Onion and apple flavonoid; the Q in dasatinib+quercetin senolytic trials; small blood pressure drop at 500 mg+/day","kw":["Senolytic and Liver","senolytic","flavonoid"],"whoNot":[{"t":"People with kidney disease","why":"High IV doses caused kidney toxicity in a trial.","conf":"reported"},{"t":"People on quinolone antibiotics","why":"Quercetin competes at the same bacterial binding site.","conf":"reported"},{"t":"People on cyclosporine or other narrow-margin drugs","why":"Inhibits CYP3A4 and P-gp; drug levels can shift.","conf":"reported"}],"kind":"supp","supp":{"cat":"Senolytic and Liver","does":"Plant flavonoid used as a natural senolytic amplifier during the Phase 0 clearance window.","benefits":"Daily intake of 500 mg or more lowers systolic blood pressure by a few mmHg in pooled trials. As a senolytic it has only been tested in humans paired with the cancer drug dasatinib in short pulses: a 2019 pilot cut senescent cell markers in fat and skin, and a 2024 phase 2 bone trial missed its primary endpoint. It does not clear senescent cells on its own in any human study, and daily antioxidant use is a different thing from pulsed senolytic dosing.","ev":"Emerging","evwhy":"Senolytic use rests on small D+Q pilots (Hickson 2019) and one null phase 2 (Farr 2024); BP effect from a 2016 meta-analysis","warn":["Dasatinib carries real risks (low blood counts, fluid around the lungs, bleeding, QT effects); D+Q outside a trial is not a supplement protocol","Headache and tingling reported at 1 g/day; generally well tolerated orally in short trials","High IV doses caused kidney toxicity in a phase I trial; avoid high doses with kidney disease"],"buy":["Label should state quercetin (anhydrous or dihydrate) per capsule, not just 'flavonoid complex'","For phytosome, the quercetin content is usually about 40% of the complex weight; check the quercetin mg, not the complex mg"],"dn":"Run during the 2 week senolytic window.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Plain aglycone is poorly absorbed and quickly conjugated in gut and liver; take with a fat-containing meal"},{"r":"IV","note":"Research only; tested in early cancer trials, not used clinically"}]}},{"slug":"s-fisetin","sid":"fisetin","name":"Fisetin","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1013,"alias":"senolytic, flavonoid","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Aging","mid":"Aging","lt":"Aging","lb":"Aging"},"dots":[]},"canva":false,"primary":"Aging","roles":["Aging"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"100-500 mg/day","freq":"Daily or pulsed","cycle":"","route":"Oral","half":"","use":"Strawberry flavonoid; the strongest senolytic of 10 flavonoids in mice; no positive human outcome trial yet","conf":"reported"},"desc":{},"syn":["FOXO4-DRI","Glutathione","Cerebrolysin"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Strawberry flavonoid; the strongest senolytic of 10 flavonoids in mice; no positive human outcome trial yet","kw":["Senolytic and Liver","senolytic","flavonoid"],"whoNot":[{"t":"People on blood thinners","why":"Fisetin has antiplatelet activity in lab studies.","conf":"inferred"},{"t":"People recovering from surgery","why":"Senescent cells help wounds close; clearing them slowed healing in mice.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Senolytic and Liver","does":"Plant senolytic that works alongside quercetin. Studied as a senolytic in Mayo Clinic research.","benefits":"In mice, fisetin was the most potent senolytic of 10 flavonoids tested and extended median and maximum lifespan when started late in life. In humans, the senolytic trials use short high-dose pulses (about 20 mg/kg/day for 2 days) and none has published a positive outcome yet. A 2026 trial at 200 mg/day in obese men reported small changes in inflammation markers, mostly when combined with exercise. It is not a proven anti-aging drug in people.","ev":"Emerging","evwhy":"Mouse data strong (Yousefzadeh 2018); Mayo AFFIRM pulse trials unpublished; first placebo-controlled human data are biomarker-only (2026)","warn":["No long-term human safety data at senolytic doses","Inhibits platelet aggregation and several CYP enzymes in lab studies; caution before surgery and with narrow-margin drugs","Pregnancy and breastfeeding: no data, avoid"],"buy":["Purity stated as a percentage (98% or higher) and mg of fisetin per capsule","For a pulse protocol, count the capsules: 20 mg/kg at 70 kg is about 1,400 mg/day"],"dn":"Run during the 2 week senolytic window.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Low water solubility and poor absorption; take with a fat-containing meal. Pulsed high doses are the trial model for senolysis"}]}},{"slug":"s-nac-n-acetylcysteine","sid":"nac-n-acetylcysteine","name":"NAC (N-Acetylcysteine)","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1014,"alias":"N-acetyl cysteine, acetylcysteine, glutathione precursor","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Protection","mid":"Organ","lt":"Organ","lb":"Organ"},"dots":[]},"canva":false,"primary":"Protection","roles":["Protection","Organ"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"600-1,200 mg/day","freq":"1-2x daily","cycle":"","route":"Oral, IV","half":"","use":"Glutathione precursor; hospital antidote for paracetamol overdose; mucus thinner; studied in addiction and OCD","conf":"reported"},"desc":{},"syn":["FOXO4-DRI","Glutathione","Cerebrolysin","LL-37","Bronchogen","Livagen"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Glutathione precursor; hospital antidote for paracetamol overdose; mucus thinner; studied in addiction and OCD","kw":["Senolytic and Liver","N-acetyl cysteine","acetylcysteine","glutathione precursor"],"whoNot":[{"t":"People with asthma","why":"NAC can provoke bronchospasm, mostly when inhaled.","conf":"verified"},{"t":"People taking nitroglycerin","why":"NAC boosts its effect; severe headache and low blood pressure.","conf":"reported"},{"t":"People with lung cancer or melanoma","why":"Antioxidant NAC accelerated tumour spread in mouse models.","conf":"reported"}],"kind":"supp","supp":{"cat":"Senolytic and Liver","does":"Glutathione precursor. Used in Phase 0 for liver support and debris clearance, and elsewhere to recycle glutathione, break down biofilm matrix with LL-37 and thin mucus with Bronchogen.","benefits":"Proven as the antidote for paracetamol (acetaminophen) overdose, given IV or orally in hospital. Orally it thins mucus and, at 1,200 mg/day, modestly reduces COPD flare-ups. Psychiatric trials (1,200-3,600 mg/day) show mixed but repeated signals in trichotillomania, cannabis use in teens and schizophrenia negative symptoms. It does not prevent hangovers or 'detox' the liver in healthy people.","ev":"Moderate","evwhy":"Strong as a prescription antidote; oral supplement uses rest on mixed RCTs (psychiatric review 2018; GlyNAC pilot 2023)","warn":["Nausea, diarrhoea and reflux are the common side effects; take with food","Inhaled NAC can cause bronchospasm; caution in asthma","Mouse studies (2014, 2015) found NAC and other antioxidants sped lung tumour and melanoma spread; avoid high doses with active cancer unless an oncologist agrees"],"buy":["Strong sulfur smell is normal; a sharp rotten-egg smell in a sealed fresh bottle suggests degradation","Store dry and closed; NAC oxidises in humid air"],"dn":"","appr":"FDA-approved as: Acetylcysteine injection, Rx, IV, acetaminophen overdose; also inhalation solution and oral effervescent tablets","routes":[{"r":"Oral","note":"Bioavailability under 10% but enough to raise cysteine and glutathione; effervescent and capsule forms both work. Hospital oral antidote regimen is 140 mg/kg, then 70 mg/kg every 4 h for 17 doses (clinical only)"},{"r":"IV","note":"Clinical only; paracetamol overdose antidote; anaphylactoid reactions in the first hour"},{"r":"Inhaled","note":"Clinical only; mucolytic; can trigger bronchospasm in asthma"}]}},{"slug":"s-milk-thistle","sid":"milk-thistle","name":"Milk Thistle","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1015,"alias":"silymarin, liver","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Organ","mid":"Protection","lt":"Protection","lb":"Protection"},"dots":[]},"canva":false,"primary":"Organ","roles":["Organ","Protection"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"420-600 mg/day extract","freq":"2-3x daily, split","cycle":"","route":"Oral, IV","half":"","use":"Silymarin seed extract, used for liver support; safe, but trials in hepatitis C, alcohol and fatty liver are mostly null","conf":"reported"},"desc":{},"syn":["FOXO4-DRI","Glutathione","Cerebrolysin","Livagen"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Silymarin seed extract, used for liver support; safe, but trials in hepatitis C, alcohol and fatty liver are mostly null","kw":["Senolytic and Liver","silymarin","liver"],"whoNot":[{"t":"People allergic to ragweed, daisies or marigolds","why":"Same plant family; allergic reactions reported.","conf":"verified"},{"t":"People with estrogen-sensitive conditions","why":"Milk thistle may have estrogen-like effects.","conf":"reported"},{"t":"People on diabetes medication","why":"Silymarin can lower blood sugar and add to diabetes drugs.","conf":"reported"}],"kind":"supp","supp":{"cat":"Senolytic and Liver","does":"Liver protection (hepatoprotection) while the body clears cellular debris.","benefits":"Very safe and widely used for the liver, but the best trials disappoint: NIH-funded trials in hepatitis C and fatty liver (NASH) found no benefit, and a Cochrane review found no effect on mortality in alcohol or viral liver disease. Small trials suggest modest blood sugar lowering in type 2 diabetes. In Europe, IV silibinin is a hospital antidote for death cap mushroom poisoning. It does not 'detox' or protect a healthy liver from alcohol.","ev":"Limited","evwhy":"NCCIH and LiverTox: HCV and NASH trials null; Cochrane (alcohol, HBV, HCV) no mortality effect","warn":["GI effects (bloating, nausea, loose stools) are the main side effects","Allergy risk in people sensitive to ragweed, chrysanthemum, marigold or daisy","May lower blood sugar; monitor with diabetes medicines"],"buy":["Silymarin percentage and mg per capsule on the label; 70-80% is standard (often measured by UV assay, which reads higher than HPLC)","NCCIH notes products with silymarin different from the label and contamination with pesticides, microbes or mycotoxins; choose third-party tested"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Use capsule or tablet extracts; the active compounds are fat soluble and barely extract into tea"},{"r":"IV","note":"Clinical only; silibinin for Amanita (death cap) poisoning in Europe"}]}},{"slug":"s-glycine","sid":"glycine","name":"Glycine","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1016,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Repair","mid":"Skin","lt":"Sleep","lb":"Sleep"},"dots":[]},"canva":false,"primary":"Repair","roles":["Repair","Skin","Sleep"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"3-10 g/day","freq":"1-2x daily; 3 g at bed","cycle":"","route":"Oral","half":"","use":"Collagen's most abundant amino acid; 3 g at bedtime improves subjective sleep quality in small trials","conf":"reported"},"desc":{},"syn":["BPC-157","TB-500","GHK-Cu","KPV","LL-37","Collagen Peptides","DSIP","BPC-157 + TB-500","Cartalax + Tβ4 + BPC-157","GHK-Cu + BPC-157","GHK-Cu + KPV","GLOW"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Collagen's most abundant amino acid; 3 g at bedtime improves subjective sleep quality in small trials","kw":["Collagen and Repair"],"whoNot":[{"t":"People on clozapine","why":"Glycine worsened symptoms in clozapine-treated patients.","conf":"reported"},{"t":"People on sedatives","why":"Glycine lowers core temperature and adds to sleepiness.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Collagen and Repair","does":"Raw collagen building block, and the most abundant amino acid in collagen. Also taken before bed as an inhibitory neurotransmitter to support sleep.","benefits":"Small Japanese trials found 3 g before bed improved subjective sleep quality and next-day alertness, likely by lowering core body temperature. It makes up about a third of collagen's amino acids, and combined with NAC (GlyNAC) it raised glutathione in older adults in a 24-person pilot. Very high doses (about 60 g/day) were tested as an add-on in schizophrenia. It is not a sedative and will not fix a sleep disorder.","ev":"Limited","evwhy":"Small sleep RCTs (Yamadera 2007, n=11 crossover); GlyNAC pilot (Kumar 2023); no large trials","warn":["Mild stomach upset or loose stools at high doses","Clozapine: glycine reduced its benefit in a schizophrenia trial; avoid together","Pregnancy and breastfeeding: a normal food amino acid, but gram-level supplement doses are not studied"],"buy":["Pharmaceutical or food grade, single ingredient","Powder is best value; a level teaspoon is about 3-4 g, weigh it once to check"],"dn":"5g extra at night with oral collagen. 3g before bed with DSIP.","appr":"In the US, only as a surgical irrigation solution and inside IV nutrition.","routes":[{"r":"Oral","note":"Sweet, dissolves easily in water; well absorbed"}]}},{"slug":"s-proline","sid":"proline","name":"Proline","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1017,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Repair","mid":"Skin","lt":"Skin","lb":"Skin"},"dots":[]},"canva":false,"primary":"Repair","roles":["Repair","Skin"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"2-3 g/day","freq":"Daily","cycle":"","route":"Oral","half":"","use":"Collagen's second most abundant amino acid; made by the body; almost no direct human trials as a supplement","conf":"reported"},"desc":{},"syn":["BPC-157","TB-500","GHK-Cu","KPV","LL-37","Collagen Peptides","BPC-157 + TB-500","Cartalax + Tβ4 + BPC-157","GHK-Cu + BPC-157","GHK-Cu + KPV","GLOW","KLOW"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Collagen's second most abundant amino acid; made by the body; almost no direct human trials as a supplement","kw":["Collagen and Repair"],"whoNot":[{"t":"People with inherited hyperprolinaemia","why":"An inherited enzyme defect means proline builds up; extra proline adds to it.","conf":"inferred"},{"t":"People with kidney disease on protein limits","why":"Extra amino acids add to the nitrogen load the kidneys must clear.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Collagen and Repair","does":"Second most abundant amino acid in collagen.","benefits":"Proline and its modified form hydroxyproline make up roughly a fifth of collagen, so it is a raw material for skin, tendon and cartilage. The body makes it from glutamate and it is plentiful in meat, dairy and collagen or gelatin. There are no controlled human trials showing that isolated proline improves skin, joints or healing; any effect is inferred from collagen and gelatin studies.","ev":"Limited","evwhy":"No RCTs of proline alone; rationale from collagen biochemistry and gelatin studies (Shaw 2017)","warn":["Avoid with inherited hyperprolinaemia (rare metabolic disorder)","Pregnancy and breastfeeding: food amino acid, isolated supplement doses not studied"],"buy":["Label should say L-proline, single ingredient","Compare cost per gram against collagen peptides, which supply about 12-15% proline plus hydroxyproline"],"dn":"","appr":"FDA-approved only as one amino acid inside IV nutrition.","routes":[{"r":"Oral","note":"Only route used; well absorbed as the free amino acid or within collagen peptides"}]}},{"slug":"s-hyaluronic-acid-oral","sid":"hyaluronic-acid-oral","name":"Hyaluronic Acid (oral)","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1018,"alias":"HA","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Skin","mid":"Skin","lt":"Skin","lb":"Skin"},"dots":[]},"canva":false,"primary":"Skin","roles":["Skin"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"120-240 mg/day","freq":"Daily","cycle":"","route":"Oral, Injection","half":"","use":"Oral hyaluronan; small, mostly industry-run trials suggest less dryness and fine wrinkles at 120 mg/day","conf":"reported"},"desc":{},"syn":["GHK-Cu","GHK-Cu + BPC-157","GHK-Cu + KPV","GLOW","KLOW"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Oral hyaluronan; small, mostly industry-run trials suggest less dryness and fine wrinkles at 120 mg/day","kw":["Collagen and Repair","HA"],"whoNot":[{"t":"People with active cancer","why":"HA binds CD44, a receptor linked to tumour growth.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Collagen and Repair","does":"Matrix hydration.","benefits":"Several small Japanese trials, mostly run by manufacturers, found 120 mg/day for 8-12 weeks reduced skin dryness and fine wrinkles versus placebo. Knee osteoarthritis trials at 200 mg/day show small symptom gains, with a 2018 review calling the evidence promising but low quality. Swallowed hyaluronan is broken down in the gut, so it does not travel to the skin intact.","ev":"Limited","evwhy":"Small, mostly industry-funded RCTs (Hsu 2021, Tashiro 2012); 2018 review of 15 reports asks for better trials","warn":["No safety signals in trials up to 12 months","Evidence is thin and largely manufacturer-funded; expect modest results at best","Pregnancy and breastfeeding: no data"],"buy":["HA or sodium hyaluronate mg per serving (aim for 120-200 mg)","Source stated: fermentation (vegan) or rooster comb (animal)"],"dn":"Oral. Topical HA serum is not covered here.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Broken down by gut bacteria; fragments may signal to tissues, mechanism unproven"},{"r":"Injection","note":"Clinical only; knee injections are a separate product with their own (also contested) evidence"},{"r":"Topical","note":"Serums hydrate the surface; not covered by this card"}]}},{"slug":"s-silicon-orthosilicic-acid","sid":"silicon-orthosilicic-acid","name":"Silicon (orthosilicic acid)","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1019,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Skin","mid":"Repair","lt":"Repair","lb":"Repair"},"dots":[]},"canva":false,"primary":"Skin","roles":["Skin","Repair"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"5-10 mg silicon/day","freq":"Daily","cycle":"","route":"Oral","half":"","use":"Trace mineral in bone and connective tissue; ch-OSA raised a collagen marker but not spine BMD in one bone trial","conf":"reported"},"desc":{},"syn":["Collagen Peptides"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Trace mineral in bone and connective tissue; ch-OSA raised a collagen marker but not spine BMD in one bone trial","kw":["Collagen and Repair"],"whoNot":[{"t":"People with kidney disease or a history of stones","why":"Silicon is cleared by the kidneys; silicate stones reported with antacids.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Collagen and Repair","does":"Collagen cross-linking.","benefits":"Silicon is found in bone and connective tissue, and dietary intake tracks with bone density in observational data. In a 12-month RCT in osteopenic women, choline-stabilised orthosilicic acid (6 or 12 mg/day) on top of calcium and vitamin D raised a bone collagen formation marker but did not change spine BMD. One 20-week trial reported smoother skin and stronger nails at 10 mg/day. Not shown to prevent fractures.","ev":"Limited","evwhy":"Two small RCTs (Spector 2008 bone; Barel 2005 skin); EFSA 2009 confirms bioavailability, not benefit","warn":["Silicon is cleared by the kidneys; avoid with significant kidney disease","Pregnancy and breastfeeding: no data","Large intakes of ch-OSA would add choline; stay under the 3.5 g/day choline UL"],"buy":["Label should state elemental silicon (Si) in mg, not the total complex weight","ch-OSA labels also list choline; 10 mg Si delivers roughly 100-200 mg choline"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Only soluble monomeric silicic acid is absorbed well; solid silica is mostly not"}]}},{"slug":"s-glucosamine","sid":"glucosamine","name":"Glucosamine","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1020,"alias":"joint, cartilage","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Bone","mid":"Bone","lt":"Bone","lb":"Bone"},"dots":[]},"canva":false,"primary":"Bone","roles":["Bone"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"1,500 mg/day","freq":"Once daily","cycle":"","route":"Oral","half":"","use":"Popular joint supplement; ACR 2019 strongly recommends against it; crystalline sulfate does better in European trials","conf":"reported"},"desc":{},"syn":["Cartalax","Cartalax + Tβ4 + BPC-157"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Popular joint supplement; ACR 2019 strongly recommends against it; crystalline sulfate does better in European trials","kw":["Collagen and Repair","joint","cartilage"],"whoNot":[{"t":"People on warfarin","why":"Case reports of INR rise and bleeding.","conf":"reported"},{"t":"People with glaucoma or high eye pressure","why":"Linked to raised intraocular pressure.","conf":"reported"},{"t":"People with shellfish allergy","why":"Most glucosamine comes from shellfish shells; reactions are rare but reported.","conf":"reported"}],"kind":"supp","supp":{"cat":"Collagen and Repair","does":"Cartilage support, listed with Cartalax.","benefits":"Results split by form. The large NIH GAIT trial (glucosamine HCl 1,500 mg/day) found no pain benefit over placebo for knee osteoarthritis overall. Prescription crystalline glucosamine sulfate, used in Europe, showed a small pain effect (effect size 0.27) in three pivotal trials, largely manufacturer-funded. It does not rebuild cartilage, and ACR 2019 and OARSI 2019 strongly recommend against it for knee and hip OA.","ev":"Limited","evwhy":"GAIT 2006 null; ACR 2019 strong against; ESCEO 2019 favours prescription crystalline sulfate only","warn":["Shellfish allergy: most glucosamine is made from shell; choose a non-shellfish source","May raise blood sugar in some people; monitor with diabetes","A 2016 RCT found a small rise in eye pressure; check pressure if you have glaucoma"],"buy":["Check the form: sulfate, not HCl; sulfate is often stabilised with sodium or potassium chloride, so note the sodium","Dose per day should read 1,500 mg glucosamine sulfate"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Once-daily 1,500 mg crystalline sulfate gave about 7x higher steady-state plasma levels than 500 mg HCl 3x daily"}]}},{"slug":"s-chondroitin","sid":"chondroitin","name":"Chondroitin","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1021,"alias":"joint, cartilage","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Bone","mid":"Bone","lt":"Bone","lb":"Bone"},"dots":[]},"canva":false,"primary":"Bone","roles":["Bone"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"800-1,200 mg/day","freq":"Once daily or split","cycle":"","route":"Oral","half":"","use":"Cartilage compound; pharma-grade 800 mg/day matched celecoxib in one trial; ACR strongly against for knee and hip","conf":"reported"},"desc":{},"syn":["Cartalax","Cartalax + Tβ4 + BPC-157"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Cartilage compound; pharma-grade 800 mg/day matched celecoxib in one trial; ACR strongly against for knee and hip","kw":["Collagen and Repair","joint","cartilage"],"whoNot":[{"t":"People on warfarin","why":"Case reports show carnitine raising INR and bleeding risk on warfarin.","conf":"reported"},{"t":"People with beef, pork or shark allergy","why":"Made from cow, pig, chicken or shark cartilage.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Collagen and Repair","does":"Cartilage support, listed with Cartalax.","benefits":"Pharmaceutical-grade chondroitin sulfate (800 mg/day, prescription in parts of Europe) reduced knee pain more than placebo and as much as celecoxib in the 2017 CONCEPT trial, which was funded by its maker. Supplement-grade products in GAIT (1,200 mg/day) did not beat placebo. ACR 2019 strongly recommends against it for knee and hip OA; hand OA is the one site with a conditional recommendation. It does not regrow cartilage.","ev":"Limited","evwhy":"CONCEPT 2017 positive (industry); GAIT 2006 null; 2019 analysis of 18 studies inconsistent; ACR and OARSI against","warn":["Mild GI upset is the main side effect","Associated with increased bleeding in people on warfarin","Pregnancy and breastfeeding: safety poorly established"],"buy":["Chondroitin sulfate mg per day (800-1,200 mg) and purity stated","Animal source stated (bovine, porcine, chicken or shark cartilage); none are vegan"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Large molecule, partly absorbed; effects take 2-3 months"}]}},{"slug":"s-collagen-peptides","sid":"collagen-peptides","name":"Collagen Peptides","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1022,"alias":"collagen","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Skin","mid":"Bone","lt":"Repair","lb":"Repair"},"dots":[]},"canva":false,"primary":"Skin","roles":["Skin","Bone","Repair"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"2.5-15 g/day","freq":"Once daily","cycle":"","route":"Oral","half":"","use":"Hydrolysed collagen; skin hydration and elasticity gains in pooled trials, but independent trials show little","conf":"reported"},"desc":{},"syn":["Cartalax","Cartalax + Tβ4 + BPC-157"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Hydrolysed collagen; skin hydration and elasticity gains in pooled trials, but independent trials show little","kw":["Collagen and Repair","collagen"],"whoNot":[{"t":"People with oxalate kidney stones","why":"Hydroxyproline in collagen is converted to oxalate.","conf":"reported"},{"t":"People with fish or beef allergy","why":"Made from fish skin or cowhide; allergic reactions are possible.","conf":"inferred"},{"t":"People with kidney disease on protein limits","why":"Collagen is protein and counts toward a restricted daily protein budget.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Collagen and Repair","does":"Oral collagen substrate. Also listed with the peptides as an optional Phase 1 item, and paired with Cartalax.","benefits":"Pooled trials show better skin hydration and elasticity after 8-12 weeks, but a 2025 meta-analysis found the benefit disappears in non-industry-funded and higher-quality trials. One 12-month trial found 5 g/day raised spine and hip BMD in postmenopausal women. 15 g of gelatin with vitamin C an hour before exercise doubled a collagen synthesis marker. It is not a complete protein and is not absorbed as intact collagen.","ev":"Limited","evwhy":"Pu 2023 meta (26 RCTs) positive; Myung 2025 meta (23 RCTs) null in independent and high-quality trials","warn":["Most positive trials were funded by collagen makers; a 2025 meta-analysis found no effect when those were set aside","Fish or bovine allergy: check source","Kidney disease on protein restriction: 15 g/day adds meaningful protein"],"buy":["Grams of collagen per scoop; match the dose to the goal (2.5-10 g skin, 5 g bone, 15 g for tendon loading)","Source stated (bovine, porcine, marine); fish-allergic users avoid marine"],"dn":"The 15g figure is the Cartalax pairing.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Digested into amino acids and small di- and tripeptides (such as prolyl-hydroxyproline) that appear in blood within 1 h"}]}},{"slug":"s-coq10-ubiquinol","sid":"coq10-ubiquinol","name":"CoQ10 (Ubiquinol)","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1023,"alias":"coenzyme Q10, ubiquinol","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Energy","mid":"Heart","lt":"Heart","lb":"Heart"},"dots":[]},"canva":false,"primary":"Energy","roles":["Energy","Heart"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"100-300 mg/day","freq":"1-2x daily, with fat","cycle":"","route":"Oral","half":"","use":"Electron carrier for mitochondrial ATP; best evidence in heart failure, mixed for statin muscle pain","conf":"reported"},"desc":{},"syn":["NAD+","MOTS-C","SS-31","SLU-PP-332","AICAR","Hexarelin","L-Carnitine injectable","Cardiogen","Vesugen","HMG","MitoPrime","SLU-PP-332 + BAM-15 oral"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Electron carrier for mitochondrial ATP; best evidence in heart failure, mixed for statin muscle pain","kw":["Mitochondria and NAD+","coenzyme Q10","ubiquinol"],"whoNot":[{"t":"People on warfarin","why":"CoQ10 is structurally like vitamin K and can reduce warfarin effect.","conf":"verified"},{"t":"People on blood pressure medicines","why":"CoQ10 can lower blood pressure slightly and add to BP drugs.","conf":"reported"},{"t":"People in chemotherapy or radiation","why":"Antioxidant may shield tumour cells.","conf":"reported"}],"kind":"supp","supp":{"cat":"Mitochondria and NAD+","does":"Electron carrier in the mitochondrial electron transport chain. Marked critical in Phase 2.","benefits":"Strongest human signal is chronic heart failure: Q-SYMBIO (420 patients, 300 mg/day for 2 years) reported fewer major cardiac events and deaths, but it is one mid-sized trial and NCCIH still calls the heart failure evidence inconclusive. May modestly cut migraine days. Statins lower body CoQ10, yet trials on statin muscle pain conflict and NCCIH reads the overall evidence as not supportive. Does not meaningfully lower blood pressure.","ev":"Moderate","evwhy":"Q-SYMBIO RCT in heart failure; statin myopathy and migraine meta-analyses mixed (NCCIH, MSK)","warn":["Mild insomnia if taken late; nausea, diarrhoea, appetite loss","Warfarin: vitamin K-like structure may weaken its effect; bleeding also reported. Recheck INR when starting or stopping","During chemotherapy or radiation: antioxidant may blunt treatment; one breast cancer cohort linked use during treatment to higher recurrence. Clear with the oncology team"],"buy":["Softgel with an oil carrier, not a dry tablet","Ubiquinol: blister or nitrogen-flushed packaging; label should say 'ubiquinol', not just 'CoQ10'"],"dn":"As ubiquinol. 200mg in the SS-31, Hexarelin, Cardiogen and L-carnitine stacks.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Only practical route. Fat-soluble: take with a meal containing fat; absorption is slow (5-8 h) and saturable per dose."}]}},{"slug":"s-pqq","sid":"pqq","name":"PQQ","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1024,"alias":"pyrroloquinoline quinone","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Energy","mid":"Energy","lt":"Energy","lb":"Energy"},"dots":[]},"canva":false,"primary":"Energy","roles":["Energy"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"10-20 mg/day","freq":"1x daily","cycle":"","route":"Oral","half":"","use":"Redox cofactor sold for mitochondrial biogenesis; human data are a few small trials on cognition and sleep","conf":"reported"},"desc":{},"syn":["NAD+","MOTS-C","SS-31","SLU-PP-332","AICAR","MitoPrime","SLU-PP-332 + BAM-15 oral"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Redox cofactor sold for mitochondrial biogenesis; human data are a few small trials on cognition and sleep","kw":["Mitochondria and NAD+","pyrroloquinoline quinone"],"whoNot":[{"t":"People with kidney disease","why":"High doses caused kidney changes in rats.","conf":"reported"}],"kind":"supp","supp":{"cat":"Mitochondria and NAD+","does":"Supports mitochondrial biogenesis.","benefits":"Human evidence is thin. One placebo-controlled trial in older adults with self-reported forgetfulness found 21 mg/day improved several cognitive scores. Mitochondrial biogenesis is shown mainly in cells and animals, with only limited human signalling data. Blood levels after oral doses are low and brain entry is uncertain. Not shown to slow ageing or raise energy in people.","ev":"Limited","evwhy":"A handful of small RCTs (cognition at 21 mg/day); most mechanism data in vitro or animal (Examine)","warn":["No long-term human safety data; EFSA's safe-intake finding excluded pregnancy and breastfeeding","Effects in people likely smaller than marketing implies: low oral blood levels, uncertain brain entry"],"buy":["Label states mg of PQQ (as disodium salt) per capsule","Third-party tested"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Only route used. Optimal dose unknown."}]}},{"slug":"s-d-ribose","sid":"d-ribose","name":"D-Ribose","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1025,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Energy","mid":"Energy","lt":"Energy","lb":"Energy"},"dots":[]},"canva":false,"primary":"Energy","roles":["Energy"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"5 g per dose","freq":"2-3x daily","cycle":"","route":"Oral, IV","half":"","use":"Five-carbon sugar used to rebuild ATP; small trials in heart disease and fatigue, no gain for healthy athletes","conf":"reported"},"desc":{},"syn":["NAD+","MOTS-C","SS-31","SLU-PP-332","AICAR","MitoPrime","SLU-PP-332 + BAM-15 oral"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Five-carbon sugar used to rebuild ATP; small trials in heart disease and fatigue, no gain for healthy athletes","kw":["Mitochondria and NAD+"],"whoNot":[{"t":"People on insulin or sulfonylureas","why":"Ribose can lower blood sugar and add to diabetes drugs.","conf":"reported"}],"kind":"supp","supp":{"cat":"Mitochondria and NAD+","does":"ATP precursor.","benefits":"Small trials suggest better exercise tolerance and tolerance of reduced blood flow in coronary artery disease (15 g 4x/day). An uncontrolled study in fibromyalgia and chronic fatigue (15 g/day) reported more energy and better sleep, but had no placebo arm. Possibly prevents post-exercise cramping in the rare myoadenylate deaminase deficiency. Does not raise strength or power in healthy, trained people; one trial did worse than a dextrose placebo.","ev":"Limited","evwhy":"Small and mostly uncontrolled trials; RxList rates CFS, fibromyalgia and heart failure as insufficient evidence","warn":["Lowers blood sugar: caution in diabetes and hypoglycaemia; stop 2 weeks before surgery","Diarrhoea, stomach upset, nausea, headache","Long-term safety unknown; no pregnancy or breastfeeding data"],"buy":["5 g per scoop, single ingredient","No added sugars or flavour blends"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Powder dissolved in water; gram doses."},{"r":"IV","note":"Clinical only: cardiac imaging and rare metabolic myopathy."}]}},{"slug":"s-alpha-lipoic-acid","sid":"alpha-lipoic-acid","name":"Alpha Lipoic Acid","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1026,"alias":"ALA","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Energy","mid":"Protection","lt":"Fat","lb":"Fat"},"dots":[]},"canva":false,"primary":"Energy","roles":["Energy","Protection","Fat"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"300-600 mg/day","freq":"1x daily, before food","cycle":"","route":"Oral, IV","half":"","use":"Mitochondrial cofactor and antioxidant; 600 mg/day eases diabetic nerve pain symptoms in multiple RCTs","conf":"reported"},"desc":{},"syn":["Glutathione","NAD+","MOTS-C","SS-31","SLU-PP-332","AICAR","L-Carnitine injectable","Livagen","MitoPrime","SLU-PP-332 + BAM-15 oral"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Mitochondrial cofactor and antioxidant; 600 mg/day eases diabetic nerve pain symptoms in multiple RCTs","kw":["Mitochondria and NAD+","ALA"],"whoNot":[{"t":"People of East Asian descent (HLA-DRB1*04:06)","why":"Can trigger insulin autoimmune syndrome with dangerous lows.","conf":"reported"},{"t":"People on levothyroxine","why":"May interfere with thyroid hormone conversion.","conf":"reported"},{"t":"Heavy drinkers or people low in thiamine","why":"Toxic in thiamine-deficient animals.","conf":"reported"}],"kind":"supp","supp":{"cat":"Mitochondria and NAD+","does":"Mitochondrial antioxidant. Also recycles glutathione and works with L-carnitine for fat oxidation.","benefits":"Best evidence is diabetic peripheral neuropathy: oral 600 mg/day reduces symptom scores (burning, pain, numbness) in RCTs and a 2025 meta-analysis of 9 trials, while nerve conduction barely changes. NATHAN 1 (4 years) showed slowed progression, not reversal. IV 600 mg works faster in clinic. 1,200-1,800 mg adds nausea, not benefit. Weight and glucose effects are small.","ev":"Moderate","evwhy":"Das 2025 meta-analysis, 9 oral RCTs (1,345 people); SYDNEY 2 dose-ranging; NATHAN 1","warn":["Insulin autoimmune syndrome: hypoglycaemia 2-6 h after meals, mainly in carriers of HLA-DRB1*04:06 (5-13% of Japanese, under 1% of Europeans; odds ratio 56.6 in Japanese and Korean patients). Reported at 200-800 mg/day; resolves months after stopping, returns on re-exposure. Most relevant for East Asian users","Lowers blood sugar: monitor with insulin or sulfonylureas","Nausea and stomach upset, worse at 1,200 mg and above"],"buy":["600 mg racemic matches the trial dose","If R-form, look for the stabilised sodium salt"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"About 30% reaches blood; food lowers absorption further, so take before meals."},{"r":"IV","note":"Clinical only, used in parts of Europe for painful neuropathy; relief from about day 8."}]}},{"slug":"s-acetyl-l-carnitine","sid":"acetyl-l-carnitine","name":"Acetyl-L-Carnitine","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1027,"alias":"ALCAR","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Energy","mid":"Fat","lt":"Fat","lb":"Fat"},"dots":[]},"canva":false,"primary":"Energy","roles":["Energy","Fat"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"1-3 g/day","freq":"split 2-3x daily","cycle":"","route":"Oral","half":"","use":"Brain-penetrant carnitine; modest evidence for low mood, especially 60+, and short-term cognitive support","conf":"reported"},"desc":{},"syn":["NAD+","MOTS-C","SS-31","SLU-PP-332","AICAR","L-Carnitine injectable","MitoPrime","SLU-PP-332 + BAM-15 oral"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Brain-penetrant carnitine; modest evidence for low mood, especially 60+, and short-term cognitive support","kw":["Mitochondria and NAD+","ALCAR"],"whoNot":[{"t":"People on levothyroxine or with hypothyroidism","why":"Carnitine blocks thyroid hormone entry into cells.","conf":"reported"},{"t":"People with bipolar disorder","why":"Hypomania has been reported in people with bipolar disorder.","conf":"reported"},{"t":"People with seizure disorders","why":"Seizures have been reported with carnitine, with or without prior history.","conf":"reported"},{"t":"People on warfarin","why":"Case reports show carnitine raising INR and bleeding risk on warfarin.","conf":"reported"}],"kind":"supp","supp":{"cat":"Mitochondria and NAD+","does":"Fatty acid shuttle into the mitochondria.","benefits":"A 2026 meta-analysis (15 studies) found 1-3 g/day reduced depressive symptoms versus placebo, with the larger effect in people 60+, but trials were small and very heterogeneous, and it did not beat antidepressants head to head. In mild cognitive impairment and early Alzheimer's, Cochrane saw benefit at 12 and 24 weeks that faded by 52 weeks. Does not burn fat or boost endurance in well-fed people; the body makes enough carnitine.","ev":"Limited","evwhy":"Pagali 2026 depression meta-analysis (high heterogeneity); Cochrane 2003 dementia review; ODS","warn":["Nausea, cramps, diarrhoea and fishy odour around 3 g/day","Seizure disorders: seizures reported with carnitine","TMAO: gut bacteria turn unabsorbed carnitine into TMAO, linked to heart disease risk; one 2022 L-carnitine trial raised LDL. Clinical meaning unclear"],"buy":["Label gives mg of acetyl-L-carnitine per capsule","Trial doses need 2-6 capsules of 500 mg daily"],"dn":"1g oral on non-injection days when using injectable L-Carnitine.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"ALC bioavailability is poorly studied; plain L-carnitine supplements absorb only 14-18%."}]}},{"slug":"s-creatine-monohydrate","sid":"creatine-monohydrate","name":"Creatine Monohydrate","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1028,"alias":"creatine","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Muscle","mid":"Energy","lt":"Energy","lb":"Energy"},"dots":[]},"canva":false,"primary":"Muscle","roles":["Muscle","Energy"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"3-5 g/day","freq":"1x daily, any time","cycle":"","route":"Oral","half":"","use":"Most-studied sports supplement: more strength, power and lean mass with training; emerging brain and ageing data","conf":"reported"},"desc":{},"syn":["NAD+","MOTS-C","SS-31","SLU-PP-332","AICAR","Retatrutide","Tirzepatide","Semaglutide","5-Amino-1MQ","L-Carnitine injectable","Lipo-C","AOD-9604"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Most-studied sports supplement: more strength, power and lean mass with training; emerging brain and ageing data","kw":["Mitochondria and NAD+","creatine"],"whoNot":[{"t":"People monitoring kidney function by creatinine","why":"Raises blood creatinine, making kidneys look worse on labs.","conf":"reported"},{"t":"People with kidney disease or on nephrotoxic drugs","why":"Case reports of kidney injury, mostly with pre-existing disease.","conf":"reported"},{"t":"People with bipolar disorder","why":"Case reports describe mania starting during creatine use.","conf":"reported"}],"kind":"supp","supp":{"cat":"Mitochondria and NAD+","does":"Phosphocreatine buffer for cellular energy. On GLP-1s it is there for muscle preservation.","benefits":"Raises muscle phosphocreatine, adding strength, power, repeated-sprint work and lean mass during resistance training, in men and women. Vegetarians, with lower stores, respond more. In older adults it adds lean mass when paired with training. Brain data are emerging: a 2024 meta-analysis of 16 RCTs found better memory (moderate certainty). Does not help endurance events, and does not damage healthy kidneys; it raises creatinine, which is not kidney injury.","ev":"Strong","evwhy":"ISSN 2017 position stand, IOC 2018 consensus, hundreds of RCTs; brain and ageing data still small","warn":["Raises serum creatinine and lowers calculated eGFR without kidney damage; tell whoever orders your bloods, or ask for cystatin C","Weight up 1-2 kg in the first month, mostly water inside muscle","Stomach upset with large single doses; split loading doses"],"buy":["Single ingredient: 'creatine monohydrate', 3-5 g per scoop","NSF Certified for Sport or Informed Sport if you are drug-tested"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Powder in water, juice or a shake; timing matters little. Taking with carbohydrate or protein may raise uptake slightly."}]}},{"slug":"s-nmn","sid":"nmn","name":"NMN","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1029,"alias":"nicotinamide mononucleotide","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Energy","mid":"Aging","lt":"Aging","lb":"Aging"},"dots":[]},"canva":false,"primary":"Energy","roles":["Energy","Aging"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"250-600 mg/day","freq":"1x daily, morning","cycle":"","route":"Oral, Sublingual","half":"","use":"NAD+ precursor; small human trials raise blood NAD+, but clinical benefits are not yet shown","conf":"reported"},"desc":{},"syn":["NAD+","MitoPrime"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"NAD+ precursor; small human trials raise blood NAD+, but clinical benefits are not yet shown","kw":["Mitochondria and NAD+","nicotinamide mononucleotide"],"whoNot":[{"t":"People with active or recent cancer","why":"Tumours depend on NAD+ for growth and DNA repair; raising it is untested in cancer.","conf":"reported"},{"t":"People on PARP inhibitors","why":"PARP enzymes run on NAD+; extra NAD+ may work against these drugs.","conf":"inferred"},{"t":"People with high homocysteine","why":"Nicotinamide clearance uses methyl groups.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Mitochondria and NAD+","does":"NAD+ precursor for baseline support between injections.","benefits":"Oral NMN reliably raises blood NAD+ in small trials (250-900 mg/day, up to 12 weeks). Turning that into outcomes has not worked so far: a 2025 meta-analysis of 8 RCTs (342 adults) found no change in glucose, insulin, HbA1c or lipids. One trial in prediabetic women showed better muscle insulin sensitivity; performance results are mixed. Nicotinamide riboside (NR) has more trials and the same pattern: NAD+ rises, few clinical effects. No proven anti-ageing effect in humans.","ev":"Emerging","evwhy":"Chen 2025 meta-analysis, 8 small RCTs, 14 days to 12 weeks; NAD+ rises, hard outcomes null","warn":["Long-term safety unknown; trials last 12 weeks at most","Part converts to nicotinamide, which uses methyl groups when cleared; why TMG is often paired (theory, untested)","Speculative: raises NAD+ in all cells, including tumour cells; avoid with active cancer until data exist [S]"],"buy":["Beta-NMN, purity 98%+ on a certificate of analysis from an independent lab","250-500 mg per serving"],"dn":"Sublingual.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"The route used in all published human trials."},{"r":"Sublingual","note":"Marketed to bypass gut breakdown; no published human comparison shows higher NAD+ than swallowing."}]}},{"slug":"s-resveratrol","sid":"resveratrol","name":"Resveratrol","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1030,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Aging","mid":"Energy","lt":"Energy","lb":"Energy"},"dots":[]},"canva":false,"primary":"Aging","roles":["Aging","Energy"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"150-500 mg/day","freq":"1x daily, morning","cycle":"","route":"Oral","half":"","use":"Grape polyphenol behind the sirtuin hype; well absorbed but rapidly metabolised, mixed human results","conf":"reported"},"desc":{},"syn":["NAD+","MitoPrime"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Grape polyphenol behind the sirtuin hype; well absorbed but rapidly metabolised, mixed human results","kw":["Mitochondria and NAD+"],"whoNot":[{"t":"People training for fitness gains","why":"Blunted training benefits in older men.","conf":"reported"},{"t":"People on blood thinners","why":"It reduces platelet clumping and can add to bleeding risk.","conf":"reported"},{"t":"Hormone-sensitive cancer (breast, prostate)","why":"It acts weakly like estrogen, which hormone-driven tumours may respond to.","conf":"reported"}],"kind":"supp","supp":{"cat":"Mitochondria and NAD+","does":"Activates SIRT1, which uses up NAD+, so it is paired with NAD+.","benefits":"About 75% of an oral dose is absorbed, but first-pass metabolism leaves very little free resveratrol in blood; most circulates as sulfate and glucuronide metabolites. Human trials (150 mg to 2 g/day) give small, inconsistent effects on glucose, blood pressure and inflammation markers. Sirtuin activation and calorie-restriction mimicry in humans remain contested. Red wine supplies trivial amounts.","ev":"Limited","evwhy":"Many small, short RCTs with inconsistent results; low free blood levels (2015 bioavailability review)","warn":["Diarrhoea, nausea, cramps at higher doses","Weak estrogen receptor activity: caution with estrogen-sensitive cancers","May affect clotting: caution with anticoagulants and before surgery"],"buy":["Label states % trans-resveratrol (98%+ for pure)","If knotweed-derived, 'emodin-free' on label"],"dn":"Taken with fat.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Morning dosing gave higher bioavailability in a repeated-dose study. Food slows absorption; it can be taken with a meal for comfort."}]}},{"slug":"s-tmg-trimethylglycine","sid":"tmg-trimethylglycine","name":"TMG (Trimethylglycine)","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1031,"alias":"betaine, methyl donor","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Energy","mid":"Energy","lt":"Energy","lb":"Energy"},"dots":[]},"canva":false,"primary":"Energy","roles":["Energy"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"500 mg-3 g/day","freq":"1-2x daily","cycle":"","route":"Oral","half":"","use":"Methyl donor that reliably lowers homocysteine; above 4 g/day it raises LDL; little else proven","conf":"reported"},"desc":{},"syn":["NAD+","MitoPrime"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Methyl donor that reliably lowers homocysteine; above 4 g/day it raises LDL; little else proven","kw":["Mitochondria and NAD+","betaine","methyl donor"],"whoNot":[{"t":"People with high LDL or heart disease","why":"Doses of 4 g a day raised LDL cholesterol.","conf":"reported"},{"t":"People with trimethylaminuria","why":"Gut bacteria can turn betaine into fishy-smelling TMA.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Mitochondria and NAD+","does":"Methyl donor. NAD+ production consumes methyl groups.","benefits":"Donates a methyl group to recycle homocysteine into methionine and reliably lowers homocysteine; in healthy adults 1.5-3 g/day works about as well as higher doses. Lower homocysteine has not been shown to prevent heart events. Sports trials suggest help with high-volume, muscular-endurance work, not maximal strength. Pairing it with NMN to offset methyl use is a theory, not tested in trials.","ev":"Limited","evwhy":"Homocysteine lowering well replicated; clinical outcomes and NAD+ pairing untested (Examine)","warn":["Above about 4 g/day raises total and LDL cholesterol; at 500 mg/day this is unlikely","Diarrhoea and nausea at high doses","Prescription betaine for CBS-deficient homocystinuria can raise methionine sharply; brain swelling reported, so medical monitoring only"],"buy":["Label reads 'betaine anhydrous' or 'trimethylglycine'","Powder is cheapest for gram doses"],"dn":"","appr":"FDA-approved as: Betaine anhydrous for oral solution, Rx, homocystinuria","routes":[{"r":"Oral","note":"Powder or capsules; the only route used."}]}},{"slug":"s-apigenin","sid":"apigenin","name":"Apigenin","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1032,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Energy","mid":"Energy","lt":"Energy","lb":"Energy"},"dots":[]},"canva":false,"primary":"Energy","roles":["Energy"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"50 mg/day","freq":"1x daily, evening","cycle":"","route":"Oral","half":"","use":"Chamomile flavone; CD38 and NAD+ claims rest on animal work, human data are chamomile for sleep and calm","conf":"reported"},"desc":{},"syn":["NAD+","MitoPrime"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Chamomile flavone; CD38 and NAD+ claims rest on animal work, human data are chamomile for sleep and calm","kw":["Mitochondria and NAD+"],"whoNot":[{"t":"People on sedatives","why":"Apigenin binds the same receptors as benzodiazepines; sedation can add up.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Mitochondria and NAD+","does":"CD38 inhibitor, which blocks a drain on NAD+.","benefits":"There are no completed human RCTs of isolated apigenin for sleep, NAD+ or ageing. Evidence comes from chamomile extracts (220-1,500 mg/day for 2-8 weeks), where small trials show modest gains in sleep quality and anxiety, and from cohort data linking dietary apigenin to better sleep. CD38 inhibition that raises NAD+ is shown in animals only.","ev":"Limited","evwhy":"No isolated-apigenin RCTs; small chamomile trials; CD38 data preclinical (Kramer and Johnson 2024)","warn":["Drowsiness: take in the evening; adds to alcohol, benzodiazepines, opioids and sedating antihistamines","Allergy risk with ragweed, daisy or marigold sensitivity (Asteraceae)","Caution with liver impairment"],"buy":["mg of apigenin and purity per capsule","For chamomile extract, the standardisation % is stated"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Poorly bioavailable: heavily glucuronidated and sulfated; peak about 1-2 h."}]}},{"slug":"s-niacin-vitamin-b3","sid":"niacin-vitamin-b3","name":"Niacin (Vitamin B3)","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1033,"alias":"B3, nicotinic acid","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Energy","mid":"Energy","lt":"Energy","lb":"Energy"},"dots":[]},"canva":false,"primary":"Energy","roles":["Energy"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"RDA 14-16 mg; UL 35 mg","freq":"1x daily, with food","cycle":"","route":"Oral","half":"","use":"Vitamin B3 and NAD+ precursor; high-dose nicotinic acid improves lipids but failed to cut heart events","conf":"reported"},"desc":{},"syn":["NAD+","5-Amino-1MQ","MitoPrime"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Vitamin B3 and NAD+ precursor; high-dose nicotinic acid improves lipids but failed to cut heart events","kw":["Mitochondria and NAD+","B3","nicotinic acid"],"whoNot":[{"t":"People with gout","why":"Niacin competes with uric acid for excretion and can trigger gout attacks.","conf":"verified"},{"t":"People with diabetes","why":"High-dose niacin worsens insulin resistance and raises blood sugar.","conf":"verified"},{"t":"People on statins","why":"High-dose niacin with statins raises the risk of muscle damage.","conf":"verified"},{"t":"People with liver disease","why":"Slow-release niacin can cause serious liver injury.","conf":"verified"}],"kind":"supp","supp":{"cat":"Mitochondria and NAD+","does":"Additional NAD+ precursor.","benefits":"Essential vitamin: prevents pellagra and feeds NAD+ synthesis. Pharmacologic nicotinic acid (1-3 g/day) lowers LDL and triglycerides and raises HDL, but adding it to statins in AIM-HIGH (3,414 people) and HPS2-THRIVE (25,673 people) cut no cardiovascular events and brought more diabetes, bleeding and GI problems. Nicotinamide, a different form, lowers new non-melanoma skin cancers in high-risk people. Flushing is not detox.","ev":"Strong","evwhy":"RDA well established; AIM-HIGH and HPS2-THRIVE show no CV benefit on top of statins (ODS)","warn":["Flushing, burning, itching above 30-50 mg nicotinic acid; worse with alcohol, heat, exercise, spicy food. Aspirin 325 mg 30-45 min before reduces it","500 mg/day of nicotinic acid is a pharmacologic dose, 14x the UL: ACC/AHA advise liver enzymes, fasting glucose or HbA1c and uric acid at baseline and every 6 months","Liver injury at 1-3 g/day, highest with sustained-release; jaundice reported around 3 g/day"],"buy":["Label names the form: nicotinic acid, nicotinamide/niacinamide, or inositol hexanicotinate","'Flush-free' usually means inositol hexanicotinate, not active niacin"],"dn":"","appr":"FDA-approved as: Niacin extended-release tablets, Rx, dyslipidaemia","routes":[{"r":"Oral","note":"Only route for supplements. Take nicotinic acid after food to soften the flush."}]}},{"slug":"s-cycloastragenol","sid":"cycloastragenol","name":"Cycloastragenol","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1034,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"DNA","mid":"Aging","lt":"Aging","lb":"Aging"},"dots":[]},"canva":false,"primary":"DNA","roles":["DNA","Aging"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"5-25 mg/day","freq":"1x daily","cycle":"","route":"Oral","half":"","use":"Astragalus-derived telomerase activator; human data are a few small, industry-funded telomere-length studies","conf":"reported"},"desc":{},"syn":["Epithalon","Pinealon","N-Acetyl Epithalon Amidate","IllumiNeuro"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Astragalus-derived telomerase activator; human data are a few small, industry-funded telomere-length studies","kw":["Telomere and Longevity"],"whoNot":[{"t":"People with active or recent cancer","why":"It activates telomerase, the enzyme most cancers use to keep dividing.","conf":"inferred"},{"t":"Transplant recipients on anti-rejection drugs","why":"Astragalus compounds stimulate immunity, which works against anti-rejection drugs.","conf":"reported"}],"kind":"supp","supp":{"cat":"Telomere and Longevity","does":"Independent telomerase activator that runs alongside Epithalon.","benefits":"Activates telomerase in cell and animal studies. The only human data come from a commercial astragalus extract built on cycloastragenol: one 12-month RCT in 97 adults aged 53-87 reported longer lymphocyte telomeres on the lower dose only, and an earlier open-label study reported fewer short telomeres and immune marker shifts. No trial shows longer life, fewer diseases or better function. It does not reverse ageing; telomere length is a marker, not an outcome.","ev":"Emerging","evwhy":"One small industry-funded RCT (Salvador 2016) and open-label work (Harley 2011); no outcome trials, no trial of the pure compound at 25 mg","warn":["Telomerase is active in about 85-90% of cancers; activating it in someone with an active or past cancer is a theoretical risk with no human safety data either way","No long-term human safety data for the pure compound at 25 mg/day","Pregnancy and breastfeeding: no data, avoid"],"buy":["Label should state mg of cycloastragenol per capsule, not mg of astragalus extract","Ask for a lot-specific certificate of analysis (HPLC purity, heavy metals)"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Low oral bioavailability in animal pharmacokinetic work; usually taken with a fat-containing meal"}]}},{"slug":"s-methylfolate","sid":"methylfolate","name":"Methylfolate","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1035,"alias":"folate, 5-MTHF","seq":"","seqNote":"","sticker":{"blocks":{"wide":"DNA","mid":"DNA","lt":"DNA","lb":"DNA"},"dots":[]},"canva":false,"primary":"DNA","roles":["DNA"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"400-800 mcg/day","freq":"1x daily","cycle":"","route":"Oral, IV / IM","half":"","use":"Active folate for DNA synthesis and homocysteine; the pregnancy neural tube evidence is for folic acid, not this form","conf":"reported"},"desc":{},"syn":["Epithalon","Pinealon","N-Acetyl Epithalon Amidate","HMG","Vitamin B12","IllumiNeuro","Lipo-C","MIC + B12"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Active folate for DNA synthesis and homocysteine; the pregnancy neural tube evidence is for folic acid, not this form","kw":["Telomere and Longevity","folate","5-MTHF"],"whoNot":[{"t":"Vegans, older adults and long-term metformin users","why":"Folate can correct the anaemia of B12 deficiency while nerve damage continues.","conf":"verified"},{"t":"People with bipolar disorder","why":"Case reports of mania on augmentation.","conf":"reported"},{"t":"People on phenytoin or other anti-seizure drugs","why":"Folate can lower phenytoin levels and trigger seizures.","conf":"verified"}],"kind":"supp","supp":{"cat":"Telomere and Longevity","does":"DNA synthesis support during the telomere phase.","benefits":"Corrects folate deficiency and lowers raised homocysteine as well as or better than folic acid, and needs no conversion by the MTHFR enzyme. Folic acid 400-800 mcg a day before conception prevents neural tube defects (USPSTF Grade A); methylfolate has no neural tube prevention trials, so it is a reasonable but unproven substitute. Prescription-strength L-methylfolate 15 mg helped as an antidepressant add-on in one positive RCT. MTHFR variants do not need special testing or 'methylated' products: ODS calls the benefit inconclusive, and the CDC still advises folic acid for carriers.","ev":"Strong","evwhy":"Folate deficiency and NTD prevention are Grade A for folic acid (USPSTF 2023); methylfolate-specific outcome data are thin (Papakostas 2012 for depression)","warn":["B12 masking: high folate corrects the anaemia of B12 deficiency while nerve damage progresses; check B12 before long-term doses above 1 mg","Prior neural tube defect pregnancy, antiepileptic use or very high risk need prescription doses (often 4 mg folic acid), not supplement doses","High-dose folic acid with B12 raised cancer incidence in a Norwegian trial and prostate cancer in a meta-analysis; avoid megadoses with a history of colorectal adenoma"],"buy":["Look for 'mcg DFE' on the label: FDA allows a factor of up to 1.7, so 400 mcg 5-MTHF can read about 680 mcg DFE","Check that the isomer is stated as L-, (6S) or a named stable salt"],"dn":"","appr":"Levomefolate is FDA-approved only as one ingredient of a combined oral contraceptive.","routes":[{"r":"Oral","note":"Absorbed well with or without food; no conversion step needed"},{"r":"IV / IM","note":"Clinical only: folinic acid (leucovorin) is the injectable form, used with methotrexate and in deficiency states"}]}},{"slug":"s-carnosine","sid":"carnosine","name":"Carnosine","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1036,"alias":"L-carnosine, Beta-alanyl-L-histidine, Histidine-containing dipeptide, HCD, Anserine/carnosine, Zinc-carnosine, Zinc L-carnosine, Polaprezinc, N-acetylcarnosine","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Aging","mid":"Glucose","lt":"Cognition","lb":"Gut"},"dots":[]},"canva":false,"primary":"Aging","roles":["Aging","Glucose","Cognition","Gut","Muscle"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"500 mg-2 g/day","freq":"1-2x daily, split","cycle":"","route":"Oral, Topical (eye)","half":"","use":"Antiglycation dipeptide; small trials show modest glucose and memory effects; beta-alanine beats it for muscle","conf":"reported"},"desc":{},"syn":[],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Antiglycation dipeptide; small trials show modest glucose and memory effects; beta-alanine beats it for muscle","kw":["Telomere and Longevity","L-carnosine","Beta-alanyl-L-histidine","Histidine-containing dipeptide","HCD","Anserine/carnosine","Zinc-carnosine","Zinc L-carnosine","Polaprezinc","N-acetylcarnosine"],"whoNot":[{"t":"People on blood pressure medicines","why":"Carnosine may lower blood pressure slightly and add to BP drugs.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Telomere and Longevity","does":"A dipeptide of beta-alanine and histidine that the body makes and stores mostly in muscle and brain, where it buffers acid, mops up reactive sugars and binds metals. Taken by mouth it is largely split by serum carnosinase, so small human trials show modest effects on post-meal glucose and memory at best. Zinc-carnosine is a separate gut-lining compound used as an ulcer drug in Japan.","benefits":"Best human signal is glycemic: in type 2 diabetes 1 g/day for 12 weeks cut HbA1c 0.6% in one Iranian RCT, while a larger-dose 2024 Australian RCT (2 g/day, 14 weeks) lowered post-load glucose but not HbA1c or fasting glucose; a 2021 meta-analysis of 4 human trials (carnosine or beta-alanine) found small reductions. Next, a 3:1 anserine/carnosine blend (1 g/day) slowed delayed-recall decline in adults 60+ over 3-6 months, and a 2021 meta-analysis of 5 trials supports a small cognitive effect. It does not raise muscle carnosine efficiently or improve performance better than beta-alanine, and its anti-aging and telomere claims rest on cell and animal work, not human outcomes. Status: sold as a dietary supplement, not an approved drug; zinc-carnosine (polaprezinc) is a prescription ulcer drug in Japan (1994) and South Korea.","ev":"Limited","evwhy":"Small RCTs (n 43-84) with mixed glucose results (Houjeghani 2018 positive, Baye 2024 partial) and anserine-led memory trials (Hisatsune 2016); meta-analyses rate few, short studies","warn":["Pregnancy and breastfeeding: no safety data","Can add to glucose-lowering drugs; watch for lows if on insulin or sulfonylureas","Large single doses (15 g) cause headache, nausea and tingling; tingling comes from released beta-alanine"],"buy":["Label should read L-carnosine (beta-alanyl-L-histidine) in mg per capsule; trial doses were 500 mg capsules taken 2-4 a day","For memory, check the anserine and carnosine amounts separately: the trial blend was 750 mg anserine + 250 mg carnosine"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Standard. Much is split by serum carnosinase (CN1) within hours; plasma rises above baseline in only half of people at 4 g, more reliably at 6 g+, gone by about 4 h"},{"r":"Topical (eye)","note":"N-acetylcarnosine drops sold for cataract; Cochrane 2017 found no trials it could include and no convincing evidence"},{"r":"Injection","note":"Niche grey-market use; no human trials; not recommended"}]}},{"slug":"s-melatonin","sid":"melatonin","name":"Melatonin","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1037,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Sleep","mid":"Endocrine","lt":"Endocrine","lb":"Endocrine"},"dots":[]},"canva":false,"primary":"Sleep","roles":["Sleep","Endocrine"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"0.3-3 mg","freq":"Nightly, 1-2 h pre-bed","cycle":"","route":"Oral immediate-release, Oral prolonged-release","half":"","use":"Body-clock hormone: best evidence for jet lag and delayed sleep timing; modest for insomnia, low doses work","conf":"reported"},"desc":{},"syn":["Epithalon","Pinealon","N-Acetyl Epithalon Amidate","Ipamorelin","CJC-1295 no DAC","Tesamorelin","Sermorelin","GHRP-2","Hexarelin","HGH","IGF-1 LR3","CJC-1295 no DAC + Ipamorelin"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Body-clock hormone: best evidence for jet lag and delayed sleep timing; modest for insomnia, low doses work","kw":["Hormone and Sleep"],"whoNot":[{"t":"People on fluvoxamine","why":"Fluvoxamine blocks melatonin breakdown and raises levels about 17-fold.","conf":"verified"},{"t":"People with autoimmune disease or on immunosuppressants","why":"Melatonin stimulates immune activity; the SmPC advises caution in autoimmune disease.","conf":"reported"},{"t":"People on warfarin","why":"INR changes have been reported with warfarin.","conf":"reported"},{"t":"People on nifedipine","why":"Melatonin may blunt the blood-pressure effect of nifedipine.","conf":"reported"}],"kind":"supp","supp":{"cat":"Hormone and Sleep","does":"Pineal support during the telomere phase, and a GH pulse amplifier at bedtime.","benefits":"Shifts the body clock: Cochrane found it 'remarkably effective' for jet lag across 5+ time zones at 0.5-5 mg near local bedtime (NNT about 2). Helps delayed sleep phase when timed early. For chronic insomnia the effect is small (sleep onset a few minutes faster); the UK and EU license 2 mg prolonged-release only for adults 55+. It is not a sedative like a sleeping pill, and more is not better: doses above 5 mg added nothing for jet lag. Small studies show 0.5 mg and 5 mg raise daytime growth hormone equally.","ev":"Moderate","evwhy":"Cochrane jet lag review (10 RCTs); EU/UK licence for 55+ insomnia; AASM 2017 rated insomnia evidence weak","warn":["Children: US paediatric ingestions rose 530% from 2012 to 2021 (CDC), with hospitalisations and 2 deaths in under-2s","Next-day drowsiness; do not drive if groggy","Pregnancy and breastfeeding: not recommended (no data; passes into milk)"],"buy":["Prefer a USP Verified or pharmacy-grade product: a 2017 study found 71% of 31 products outside 10% of label, ranging from -83% to +478%","Choose the lowest dose that works; split tablets are fine for immediate-release, never for prolonged-release"],"dn":"0.5-3mg in Phase 3. 0.3-0.5mg at bed with GH peptides. 0.5-1mg with Pinealon.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral immediate-release","note":"Fast peak; better for sleep onset and jet lag"},{"r":"Oral prolonged-release","note":"Licensed form for 55+ insomnia; Cochrane found a 2 mg slow-release product weak for jet lag"},{"r":"Sublingual","note":"Faster onset, no evidence of better outcomes"}]}},{"slug":"s-l-arginine","sid":"l-arginine","name":"L-Arginine","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1038,"alias":"arginine","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Endocrine","mid":"Endocrine","lt":"Endocrine","lb":"Endocrine"},"dots":[]},"canva":false,"primary":"Endocrine","roles":["Endocrine"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"3-6 g/day","freq":"1-3x daily","cycle":"","route":"Oral, IV","half":"","use":"Nitric oxide precursor: small blood pressure drop; GH effect inconsistent; citrulline raises arginine better","conf":"reported"},"desc":{},"syn":["Ipamorelin","CJC-1295 no DAC","Tesamorelin","Sermorelin","GHRP-2","Hexarelin","HGH","IGF-1 LR3","CJC-1295 no DAC + Ipamorelin","Tesamorelin + Ipamorelin + CJC-1295 no DAC","Tesamorelin + Ipamorelin"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Nitric oxide precursor: small blood pressure drop; GH effect inconsistent; citrulline raises arginine better","kw":["Hormone and Sleep","arginine"],"whoNot":[{"t":"People recovering from a heart attack","why":"VINTAGE MI: more deaths with arginine.","conf":"verified"},{"t":"People prone to cold sores or genital herpes","why":"Arginine supports herpes virus replication.","conf":"reported"},{"t":"People on PDE5 inhibitors or nitrates","why":"Arginine boosts nitric oxide; with these drugs pressure can drop too far.","conf":"reported"}],"kind":"supp","supp":{"cat":"Hormone and Sleep","does":"Potentiates GH release.","benefits":"Raises nitric oxide substrate. Meta-analysed trials show a small blood pressure drop (about 5 mmHg systolic at 4-24 g/day) and some benefit in angina, peripheral artery disease and organic erectile dysfunction. Resting oral doses of 5-9 g can raise growth hormone, but ODS calls the GH and IGF-1 results conflicting, and taking it before exercise blunts the exercise GH rise. It does not improve sports performance in trained athletes, and most oral arginine is broken down in the gut before it reaches blood.","ev":"Limited","evwhy":"BP meta-analysis (Dong 2011); ODS finds little performance effect; VINTAGE MI showed harm after heart attack","warn":["After a heart attack: do not use. The VINTAGE MI trial had 6 deaths on arginine vs 0 on placebo (8.6%) and was stopped early","Low blood pressure or on nitrates or PDE5 drugs: added BP drop","Asthma and allergies: may worsen airway inflammation"],"buy":["Check grams of L-arginine per serving; capsules are often 500 mg, so 5 g means 10 capsules and powder is more practical","HCl form: about 83% arginine by weight"],"dn":"Taken about 30 minutes before the injection, before bed.","appr":"FDA-approved as: Arginine hydrochloride injection, Rx, IV, diagnostic test of pituitary growth hormone reserve","routes":[{"r":"Oral","note":"Heavy first-pass breakdown by gut arginase limits blood levels"},{"r":"IV","note":"Clinical only: GH stimulation testing and some hospital uses"},{"r":"Topical","note":"Used in some diabetic wound and sexual creams; thin evidence"}]}},{"slug":"s-gaba","sid":"gaba","name":"GABA","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1039,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Endocrine","mid":"Sleep","lt":"Sleep","lb":"Sleep"},"dots":[]},"canva":false,"primary":"Endocrine","roles":["Endocrine","Sleep"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"100-750 mg","freq":"1x daily, before bed","cycle":"","route":"Oral","half":"","use":"Calming neurotransmitter as a supplement; weak sleep and stress data, unclear if it reaches the brain","conf":"reported"},"desc":{},"syn":["Ipamorelin","CJC-1295 no DAC","Tesamorelin","Sermorelin","GHRP-2","Hexarelin","HGH","IGF-1 LR3","CJC-1295 no DAC + Ipamorelin","Tesamorelin + Ipamorelin + CJC-1295 no DAC","Tesamorelin + Ipamorelin"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Calming neurotransmitter as a supplement; weak sleep and stress data, unclear if it reaches the brain","kw":["Hormone and Sleep"],"whoNot":[{"t":"People on blood pressure medicines","why":"Oral GABA lowers blood pressure modestly and can add to BP drugs.","conf":"reported"}],"kind":"supp","supp":{"cat":"Hormone and Sleep","does":"Independent GH support, taken before bed.","benefits":"Small, mostly industry-funded trials suggest 100-300 mg taken for 1-8 weeks may shorten time to fall asleep, and 20-100 mg may blunt stress markers; a 2020 systematic review called the sleep evidence very limited. Whether oral GABA crosses the blood-brain barrier is unresolved; any effect may run through the gut and vagus nerve. Japan sells it widely as a food with function claims (sleep, stress, blood pressure). One 11-man study found 3 g raised resting growth hormone about 400%; no data exist at bedtime doses.","ev":"Limited","evwhy":"Hepsomali 2020 review of 14 small trials (11 with industry authors); BBB question open (Boonstra 2015)","warn":["Additive drowsiness with alcohol, sleeping pills, benzodiazepines and gabapentinoids","May lower blood pressure slightly; watch for dizziness on BP drugs","Pregnancy and breastfeeding: not enough data"],"buy":["Check mg of GABA per capsule and whether it is fermented or synthetic","Third-party testing (USP, NSF) is uncommon; look for it"],"dn":"Before bed.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Capsule, powder, or fermented foods (tea, rice, chocolate in Japan)"}]}},{"slug":"s-tart-cherry-extract","sid":"tart-cherry-extract","name":"Tart Cherry Extract","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1040,"alias":"sleep","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Sleep","mid":"Sleep","lt":"Sleep","lb":"Sleep"},"dots":[]},"canva":false,"primary":"Sleep","roles":["Sleep"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"480 mg or 30 mL conc.","freq":"1-2x daily","cycle":"","route":"Oral","half":"","use":"Montmorency cherry polyphenols: small trials for sleep time, exercise soreness and gout flares","conf":"reported"},"desc":{},"syn":["Pinealon","DSIP","IllumiNeuro"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Montmorency cherry polyphenols: small trials for sleep time, exercise soreness and gout flares","kw":["Hormone and Sleep","sleep"],"whoNot":[{"t":"People with IBS or sorbitol intolerance","why":"Tart cherry is rich in sorbitol, which triggers bloating and diarrhoea in IBS.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Hormone and Sleep","does":"Natural melatonin source.","benefits":"Small trials suggest modest gains in total sleep time (one 20-person trial about 25-35 minutes; one 8-person trial in older insomniacs about 84 minutes) and mixed results for post-exercise soreness and strength recovery. Cherry intake was linked to about 35% fewer gout flares in an observational study. It is not a meaningful melatonin source: the melatonin content is in nanograms, far below a 0.3 mg tablet, so any sleep effect likely runs through other compounds.","ev":"Limited","evwhy":"Small RCTs (Howatson 2012, n=20; Losso 2018, n=8); ODS rates exercise recovery results as variable","warn":["Juice sugar load matters for diabetes and weight loss goals","Sorbitol and fructose can cause bloating or loose stools","Pregnancy: food amounts are fine; concentrated extracts have no data"],"buy":["Label should say Montmorency (Prunus cerasus)","Capsules should state mg of powder or extract and, ideally, anthocyanin content"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Juice, concentrate, or capsules of powder or extract"}]}},{"slug":"s-protein","sid":"protein","name":"Protein","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1041,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Muscle","mid":"Muscle","lt":"Muscle","lb":"Muscle"},"dots":[]},"canva":false,"primary":"Muscle","roles":["Muscle"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"1.6-2 g/kg/day","freq":"20-40 g per meal, 3-4x","cycle":"","route":"Oral","half":"","use":"Builds and keeps muscle with resistance training; the key nutrient for preserving lean mass on GLP-1 drugs","conf":"reported"},"desc":{},"syn":["Retatrutide","Tirzepatide","Semaglutide","5-Amino-1MQ","L-Carnitine injectable","Lipo-C","AOD-9604","HGH Fragment 176-191","Survodutide","Mazdutide","Eloralintide","BPC-157 + TB-500"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Builds and keeps muscle with resistance training; the key nutrient for preserving lean mass on GLP-1 drugs","kw":["Metabolic and GLP-1 Support"],"whoNot":[{"t":"People with chronic kidney disease","why":"KDIGO guidance limits protein in CKD to slow kidney decline.","conf":"verified"},{"t":"People with phenylketonuria","why":"Many powders sweetened with aspartame.","conf":"verified"},{"t":"Heavy daily plant protein users","why":"Consumer Reports found lead in many plant protein powders at a daily serving.","conf":"reported"}],"kind":"supp","supp":{"cat":"Metabolic and GLP-1 Support","does":"Non-negotiable on GLP-1 agonists. Without enough, you lose muscle alongside fat.","benefits":"Adding protein to resistance training increases lean mass and strength gains (49-RCT meta-analysis), with benefit flattening around 1.6 g/kg/day (upper confidence limit 2.2). Older adults need more per meal to trigger muscle building (about 25-30 g, 2.5-3 g leucine). On GLP-1 drugs, a 2025 joint advisory pairs adequate protein with strength training 3x a week, because protein alone likely does not stop lean mass loss. Protein powder is a convenience, not superior to food.","ev":"Strong","evwhy":"Morton 2018 BJSM meta-analysis; ISSN 2017 position stand; 2025 joint GLP-1 nutrition advisory","warn":["Chronic kidney disease (stage 3-5, not on dialysis): KDIGO 2024 says 0.8 g/kg/day and not above 1.3 g/kg/day if at risk of progression","No harm shown in healthy kidneys up to about 2 g/kg/day; the GLP-1 advisory advises against prolonged intake at 2 g/kg+","Using actual body weight in obesity overestimates needs; use goal or adjusted weight, or 1.5 g per kg of fat-free mass"],"buy":["Aim for 20-30 g protein per scoop with about 2-3 g leucine","Choose NSF Certified for Sport or Informed Sport: a 2025 test found over two-thirds of 23 powders exceeded a daily lead level of concern in one serving, plant powders worst"],"dn":"Per kg of body weight, as a minimum.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Food first; powders and shakes fill gaps when appetite is suppressed"}]}},{"slug":"s-electrolytes","sid":"electrolytes","name":"Electrolytes","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1042,"alias":"sodium, potassium","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Heart","mid":"Organ","lt":"Organ","lb":"Organ"},"dots":[]},"canva":false,"primary":"Heart","roles":["Heart","Organ"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"Na 2-3g, K 3-4g, Mg 400mg","freq":"Daily, split","cycle":"","route":"Oral, IV","half":"","use":"Sodium, potassium, magnesium to cover sweat, GI losses and low intake on GLP-1s; overdrinking water is the real risk","conf":"reported"},"desc":{},"syn":["Retatrutide","Tirzepatide","Semaglutide","5-Amino-1MQ","L-Carnitine injectable","Lipo-C","AOD-9604","HGH Fragment 176-191","Survodutide","Mazdutide","Eloralintide","MitoPrime"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Sodium, potassium, magnesium to cover sweat, GI losses and low intake on GLP-1s; overdrinking water is the real risk","kw":["Metabolic and GLP-1 Support","sodium","potassium"],"whoNot":[{"t":"People on ACE inhibitors, ARBs or spironolactone","why":"These drugs hold potassium in; added potassium can climb to dangerous levels.","conf":"verified"},{"t":"People on lithium","why":"Lithium tracks sodium; big swings push lithium up or down.","conf":"reported"},{"t":"People with kidney disease","why":"Cannot excrete potassium and magnesium.","conf":"verified"}],"kind":"supp","supp":{"cat":"Metabolic and GLP-1 Support","does":"Sodium, potassium and magnesium. GLP-1s cause fluid shifts.","benefits":"Replacing sodium and fluid matters in endurance work over an hour, heat, and illness with vomiting or diarrhoea, including GI side effects on GLP-1 drugs where dehydration can injure the kidneys. Potassium-enriched salt substitute cut stroke, cardiovascular events and death by about 12-14% in a 20,995-person trial, but that is food salt, not pills. Electrolyte drinks do not prevent cramps reliably, and drinking water beyond thirst, not low salt intake, is the main cause of exercise hyponatraemia.","ev":"Moderate","evwhy":"NASEM 2019 intakes; SSaSS 2021 (salt substitute); exercise hyponatraemia cohort data (Almond 2005); GLP-1 advisory 2025 on dehydration","warn":["Kidney disease, heart failure, type 1 diabetes, adrenal insufficiency: hyperkalaemia risk even below the potassium AI","Salt substitutes carry 440-2,800 mg potassium per teaspoon; avoid them with kidney disease or on ACE inhibitors, ARBs or potassium-sparing diuretics unless a doctor approves","Exercise hyponatraemia: 13% of 2002 Boston Marathon finishers studied had low sodium, mostly from overdrinking; weight gain during a race is the warning sign. Drink to thirst"],"buy":["Read sodium in mg per serving: daily mixes run 200-1,000 mg; count it toward a 2,300 mg day if you have high blood pressure","Magnesium is listed as elemental mg; supplemental amounts above 350 mg/day exceed the UL and often cause diarrhoea"],"dn":"","appr":"FDA-approved as: Potassium chloride extended-release tablets, Rx, hypokalaemia; also IV sodium/potassium/magnesium solutions","routes":[{"r":"Oral","note":"Food, salt, drink mixes, tablets"},{"r":"IV","note":"Clinical only: severe dehydration or symptomatic hyponatraemia; 'IV drip bar' hydration offers nothing oral fluids cannot in healthy people"}]}},{"slug":"s-fiber","sid":"fiber","name":"Fiber","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1043,"alias":"fibre","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Gut","mid":"Gut","lt":"Gut","lb":"Gut"},"dots":[]},"canva":false,"primary":"Gut","roles":["Gut"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"10-15 g/day","freq":"1-2x daily, with water","cycle":"","route":"Oral","half":"","use":"Psyllium lowers LDL about 0.33 mmol/L at 10 g/day and eases constipation, the top GLP-1 complaint","conf":"reported"},"desc":{},"syn":["Retatrutide","Tirzepatide","Semaglutide","5-Amino-1MQ","L-Carnitine injectable","Lipo-C","AOD-9604","HGH Fragment 176-191","Survodutide","Mazdutide","MitoPrime","Retatrutide + Cagrilintide"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Psyllium lowers LDL about 0.33 mmol/L at 10 g/day and eases constipation, the top GLP-1 complaint","kw":["Metabolic and GLP-1 Support","fibre"],"whoNot":[{"t":"People on GLP-1 drugs or with gastroparesis","why":"Bulky fibre in a slow stomach can form a blocking mass (bezoar).","conf":"reported"},{"t":"People with bowel strictures (Crohn’s)","why":"Bulk fibre can lodge at a narrowed bowel segment and block it.","conf":"reported"},{"t":"People on levothyroxine or timed medicines","why":"Fibre binds some drugs and lowers absorption; space doses apart.","conf":"reported"}],"kind":"supp","supp":{"cat":"Metabolic and GLP-1 Support","does":"GI support. Constipation is the number one complaint on GLP-1s.","benefits":"Best evidence is for psyllium: about 10 g/day lowers LDL by about 0.33 mmol/L and apoB (28 RCTs), carries an FDA heart health claim, and improves stool form in constipation and IBS. Soluble viscous fibre also blunts post-meal glucose and adds fullness. Fermentable fibres (inulin) feed gut bacteria but cause more gas. Does not: all 'fiber' is not equal; non-viscous fibres like inulin and methylcellulose do not lower cholesterol meaningfully.","ev":"Strong","evwhy":"Jovanovski 2018 AJCN meta-analysis of 28 RCTs (psyllium, LDL, GRADE moderate); FDA psyllium CHD claim; ACG IBS guidance","warn":["Take each dose with a full glass of water; dry psyllium can swell and cause oesophageal or bowel obstruction","Avoid with swallowing problems, bowel strictures or prior obstruction","Start low and build over 1-2 weeks; fast increases cause gas and bloating"],"buy":["Check grams of fibre per serving, not grams of powder (psyllium husk is about 70-80% soluble fibre)","Unflavoured psyllium avoids sugar and sweeteners; sugar-free versions may contain aspartame (phenylketonuria warning)"],"dn":"10g/day in the Retatrutide stack.","appr":"FDA OTC drug (monograph): Psyllium (husk, seed, hydrophilic mucilloid), OTC bulk-forming laxative","routes":[{"r":"Oral","note":"Powder, capsules or wafers. Each 5 g dose needs about 250 ml of water."}]}},{"slug":"s-ginger","sid":"ginger","name":"Ginger","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1044,"alias":"nausea","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Gut","mid":"Gut","lt":"Gut","lb":"Gut"},"dots":[]},"canva":false,"primary":"Gut","roles":["Gut"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"250 mg-1 g/day","freq":"250 mg up to 4x daily","cycle":"","route":"Oral, Topical","half":"","use":"Eases nausea of pregnancy (ACOG option) and may trim chemo nausea; useful for GLP-1 queasiness","conf":"reported"},"desc":{},"syn":["Retatrutide","Tirzepatide","Semaglutide","PT-141","Retatrutide + Cagrilintide"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Eases nausea of pregnancy (ACOG option) and may trim chemo nausea; useful for GLP-1 queasiness","kw":["Metabolic and GLP-1 Support","nausea"],"whoNot":[{"t":"People on blood thinners","why":"Ginger may reduce platelet clumping and add to bleeding risk.","conf":"reported"},{"t":"People with gallstones","why":"Ginger increases bile flow, which can provoke gallstone pain.","conf":"reported"},{"t":"People on diabetes medication","why":"Ginger can lower blood sugar and add to diabetes drugs.","conf":"reported"}],"kind":"supp","supp":{"cat":"Metabolic and GLP-1 Support","does":"Anti-nausea. Also a natural option for the nausea PT-141 can cause.","benefits":"Best supported for nausea and vomiting of pregnancy, where ACOG lists it as a reasonable non-drug option. In chemotherapy it may add a little on top of standard antiemetics (largest trial: 0.5-1 g/day helped acute nausea), but results are mixed. Some evidence for menstrual cramps and knee osteoarthritis pain. Does not: reliably prevent motion sickness, and no trial shows it treats GLP-1 nausea specifically (inferred use).","ev":"Moderate","evwhy":"Pregnancy nausea RCTs supporting ACOG 2018; Ryan 2012 URCC trial (n=576) in chemo; NCCIH 2025 summary","warn":["Heartburn, burping, diarrhoea and mouth irritation, more at higher doses","Antiplatelet effect: stop about 2 weeks before surgery and avoid with bleeding disorders","Pregnancy: keep to about 1 g/day and short courses; limited data near term and in breastfeeding"],"buy":["Label should give mg of ginger root or extract per capsule and gingerol percentage for extracts","For pregnancy pick plain ginger, not blends with other herbs"],"dn":"Ginger extract.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Capsule, tea or fresh root; capsules give a known dose"},{"r":"Topical","note":"Used on skin, no proven pain benefit (NCCIH)"},{"r":"Aromatherapy","note":"Inhaled ginger oil for post-op nausea: weak evidence"}]}},{"slug":"s-digestive-enzymes","sid":"digestive-enzymes","name":"Digestive Enzymes","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1045,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Gut","mid":"Gut","lt":"Gut","lb":"Gut"},"dots":[]},"canva":false,"primary":"Gut","roles":["Gut"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"Per meal, enzyme specific","freq":"With first bite","cycle":"","route":"Oral","half":"","use":"Lactase and alpha-galactosidase work for dairy and bean gas; broad blends lack evidence","conf":"reported"},"desc":{},"syn":["Retatrutide","Tirzepatide","Semaglutide","Retatrutide + Cagrilintide"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Lactase and alpha-galactosidase work for dairy and bean gas; broad blends lack evidence","kw":["Metabolic and GLP-1 Support"],"whoNot":[{"t":"People avoiding pork or allergic to it","why":"Pancreatin and pancrelipase are made from pig pancreas.","conf":"verified"},{"t":"People allergic to pineapple, papaya or latex","why":"Bromelain and papain are fruit enzymes that cross-react with these allergies.","conf":"reported"},{"t":"People on blood thinners","why":"Bromelain/papain antiplatelet effect.","conf":"reported"},{"t":"Very high pancreatic enzyme users","why":"Fibrosing colonopathy at high doses.","conf":"verified"}],"kind":"supp","supp":{"cat":"Metabolic and GLP-1 Support","does":"Taken with meals on GLP-1s.","benefits":"Targeted enzymes have real evidence: lactase reduces symptoms from a dairy load in lactose intolerance, and alpha-galactosidase (about 1,200 GalU) reduces gas from beans and cruciferous vegetables. Prescription pancreatic enzymes (PERT) are a proven treatment for pancreatic insufficiency (cystic fibrosis, chronic pancreatitis, pancreatic surgery). Does not: broad over-the-counter blends have no good trials for bloating, 'better digestion' or GLP-1 symptoms, and they are not a substitute for PERT.","ev":"Limited","evwhy":"Strong for PERT (prescription); moderate for lactase and alpha-galactosidase; no RCT support for broad OTC blends","warn":["Oily, floating stools, weight loss or diarrhoea after fatty meals suggest pancreatic insufficiency: get tested, don't self-treat","Very high-dose pancreatic enzymes are linked to fibrosing colonopathy (mainly children with cystic fibrosis)","Porcine-derived pancreatin: not suitable for vegans, some religious diets, or pork allergy"],"buy":["Look for activity units (FCC lactase units, GalU, USP lipase units), not milligrams","Match the enzyme to the trigger food: dairy needs lactase, beans need alpha-galactosidase"],"dn":"","appr":"FDA-approved as: Pancrelipase delayed-release capsules, Rx, exocrine pancreatic insufficiency","routes":[{"r":"Oral","note":"Taken with the first bite so the enzyme meets the food; enteric coating matters for lipase"}]}},{"slug":"s-green-tea-extract","sid":"green-tea-extract","name":"Green Tea Extract","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1046,"alias":"EGCG","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Fat","mid":"Fat","lt":"Fat","lb":"Fat"},"dots":[]},"canva":false,"primary":"Fat","roles":["Fat"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"250-500 mg extract/day","freq":"1-2x daily with food","cycle":"","route":"Oral","half":"","use":"Small fat-oxidation nudge; EGCG at 800 mg/day or more raises liver enzymes, so dose and food matter","conf":"reported"},"desc":{},"syn":["5-Amino-1MQ","AOD-9604","HGH Fragment 176-191","MitoPrime"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Small fat-oxidation nudge; EGCG at 800 mg/day or more raises liver enzymes, so dose and food matter","kw":["Metabolic and GLP-1 Support","EGCG"],"whoNot":[{"t":"People taking it fasted or on an empty stomach","why":"Fasting dosing raises liver injury risk.","conf":"reported"},{"t":"People carrying HLA-B*35:01","why":"Linked to green tea extract liver injury.","conf":"reported"},{"t":"People on nadolol","why":"Green tea cut nadolol levels about 85%.","conf":"reported"},{"t":"People with iron deficiency","why":"Catechins bind iron in the gut and lower absorption from food.","conf":"reported"}],"kind":"supp","supp":{"cat":"Metabolic and GLP-1 Support","does":"Mild NNMT inhibition and fat oxidation with 5-Amino-1MQ. Amplifies lipolysis with AOD-9604.","benefits":"Catechins plus caffeine slightly raise energy expenditure and fat oxidation, but weight loss is tiny: Cochrane found about 0 kg in trials outside Japan. Green tea as a drink links to modest LDL and blood pressure reductions in cohorts and trials. Does not: produce meaningful fat loss alone, or 'burn fat' on a fasted stomach; fasted, high-dose use is exactly where liver injury clusters.","ev":"Limited","evwhy":"Cochrane 2012 (18 RCTs): weight loss small and not clinically important; EFSA 2018 liver safety opinion","warn":["Liver injury: rare but can be severe, often 1-6 months after starting; stop with dark urine, jaundice, fatigue or right-upper abdominal pain","Avoid with existing liver disease; HLA-B*35:01 carriers appear more susceptible","Pregnancy and breastfeeding: avoid extracts; EGCG may impair folate uptake"],"buy":["Find EGCG mg per serving, not just extract mg or '% polyphenols'; daily total should sit well below 800 mg","Check caffeine per serving (decaf options exist) if sensitive or sleeping poorly"],"dn":"","appr":"FDA-approved as: Sinecatechins 15% ointment (green tea catechin extract), Rx, topical, external genital and perianal warts","routes":[{"r":"Oral","note":"Capsules or brewed tea. Take with a meal: fasting bolus doses raise EGCG blood levels several-fold"}]}},{"slug":"s-l-carnitine","sid":"l-carnitine","name":"L-Carnitine","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1047,"alias":"carnitine","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Fat","mid":"Energy","lt":"Energy","lb":"Energy"},"dots":[]},"canva":false,"primary":"Fat","roles":["Fat","Energy"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"1-2 g/day","freq":"1-2x daily with carbs","cycle":"","route":"Oral, IV","half":"","use":"Fixes true deficiency (dialysis, valproate); for fat loss and performance, effects are small and mixed","conf":"reported"},"desc":{},"syn":["SLU-PP-332","AOD-9604","HGH Fragment 176-191","SLU-PP-332 + BAM-15 oral"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Fixes true deficiency (dialysis, valproate); for fat loss and performance, effects are small and mixed","kw":["Metabolic and GLP-1 Support","carnitine"],"whoNot":[{"t":"People on levothyroxine or with hypothyroidism","why":"Carnitine blocks thyroid hormone entry into cells.","conf":"reported"},{"t":"People with heart disease or high TMAO","why":"Gut bacteria turn carnitine into TMAO.","conf":"reported"},{"t":"People with seizure disorders","why":"Seizures have been reported with carnitine, with or without prior history.","conf":"reported"},{"t":"People on warfarin","why":"Case reports show carnitine raising INR and bleeding risk on warfarin.","conf":"reported"}],"kind":"supp","supp":{"cat":"Metabolic and GLP-1 Support","does":"Transports fatty acids so they can be burned.","benefits":"Clear benefit only in deficiency: genetic transporter defects, dialysis, and drugs like valproate. In the general population, the body makes enough. Trials show small extras: about 1.3 kg more weight loss (9 trials), modest fasting glucose and HbA1c drops (2023 meta-analysis), better sperm motility, and L-carnitine L-tartrate may reduce markers of muscle damage after training. Does not: reliably improve endurance performance or 'burn fat' by itself; oral absorption is only about 14-18%.","ev":"Limited","evwhy":"NIH ODS: mixed exercise data; 2016 weight meta-analysis (9 RCTs) equivocal; strong only for prescription use in deficiency","warn":["About 3 g/day causes nausea, cramps, diarrhoea and fishy body odour","TMAO: gut bacteria turn unabsorbed carnitine into TMAO, linked to atherosclerosis; a 2022 trial saw higher total and LDL cholesterol","Seizure disorders: seizures reported"],"buy":["Check whether the label gives L-carnitine content or salt weight (LCLT 1 g gives about 680 mg L-carnitine)","Pure L form only; no DL-carnitine"],"dn":"Oral. The injectable form is a separate compound.","appr":"FDA-approved as: Levocarnitine tablets, oral solution and injection, Rx, primary and secondary carnitine deficiency incl. dialysis","routes":[{"r":"Oral","note":"Main route for supplements; poor absorption, unabsorbed carnitine becomes TMAO in the gut"},{"r":"IV","note":"Clinical only: prescription levocarnitine for dialysis deficiency and valproate toxicity"},{"r":"IM / subcutaneous","note":"Injected 'lipo' carnitine is outside approved medical use; no good fat-loss trials"}]}},{"slug":"s-chromium-picolinate","sid":"chromium-picolinate","name":"Chromium Picolinate","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1048,"alias":"chromium","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Glucose","mid":"Glucose","lt":"Glucose","lb":"Glucose"},"dots":[]},"canva":false,"primary":"Glucose","roles":["Glucose"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"200-400 mcg/day","freq":"once daily with food","cycle":"","route":"Oral, IV","half":"","use":"Tiny drops in glucose and HbA1c in diabetes; weight effect under 1 kg, so mostly marketing","conf":"reported"},"desc":{},"syn":["Tesamorelin","Pancragen","Tesamorelin + Ipamorelin + CJC-1295 no DAC","Tesamorelin + Ipamorelin"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Tiny drops in glucose and HbA1c in diabetes; weight effect under 1 kg, so mostly marketing","kw":["Metabolic and GLP-1 Support","chromium"],"whoNot":[{"t":"People with kidney or liver disease","why":"Case reports link chromium picolinate to kidney failure and liver injury.","conf":"reported"},{"t":"People on insulin or sulfonylureas","why":"It can lower blood sugar and add to diabetes drugs.","conf":"reported"},{"t":"People on levothyroxine","why":"Chromium lowers levothyroxine absorption; take them hours apart.","conf":"verified"}],"kind":"supp","supp":{"cat":"Metabolic and GLP-1 Support","does":"Insulin sensitivity support.","benefits":"In people with type 2 diabetes, a 2019 review of 58 trials found slight drops in fasting glucose and HbA1c of unclear clinical value; other large trials found nothing. Weight loss is about 0.75 kg over 9-24 weeks. No benefit shown in people with normal glucose. Does not: replace diabetes treatment; the ADA says evidence is insufficient.","ev":"Limited","evwhy":"NIH ODS summary: 2019 review of 58 RCTs (small glucose effect), 2019 weight meta-analysis of 21 RCTs, ADA not recommended","warn":["Case reports at high doses: kidney failure, liver dysfunction, rhabdomyolysis, anaemia, low platelets","Avoid or use only with care in kidney or liver disease","Hypoglycaemia when stacked with insulin, metformin or berberine"],"buy":["Look for elemental chromium in mcg; chromium picolinate is only 12.4% chromium by weight","200 mcg per capsule is the standard serving; multivitamins often already have 35-120 mcg"],"dn":"200-400mcg with Tesamorelin. 200mcg with Pancragen.","appr":"Chromium is FDA-approved only as chromic chloride for IV nutrition; the picolinate form is not.","routes":[{"r":"Oral","note":"Absorption is very low (about 0.4-2.5%); picolinate about 1.2%"},{"r":"IV","note":"Clinical only, as part of parenteral nutrition"}]}},{"slug":"s-berberine","sid":"berberine","name":"Berberine","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1049,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Glucose","mid":"Glucose","lt":"Glucose","lb":"Glucose"},"dots":[]},"canva":false,"primary":"Glucose","roles":["Glucose"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"500 mg 2-3x/day","freq":"with meals","cycle":"","route":"Oral","half":"","use":"Modest drops in post-meal glucose, LDL and triglycerides; not a GLP-1 drug and off-limits in pregnancy","conf":"reported"},"desc":{},"syn":["Tesamorelin","HGH","Pancragen","Tesamorelin + Ipamorelin + CJC-1295 no DAC","Tesamorelin + Ipamorelin"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Modest drops in post-meal glucose, LDL and triglycerides; not a GLP-1 drug and off-limits in pregnancy","kw":["Metabolic and GLP-1 Support"],"whoNot":[{"t":"People on cyclosporine or tacrolimus","why":"Berberine raised cyclosporine levels.","conf":"reported"},{"t":"People on metformin or insulin","why":"Berberine lowers glucose by similar routes and stacks with these drugs.","conf":"reported"},{"t":"People on CYP2D6 or CYP3A4 drugs","why":"Berberine blocks these liver enzymes and can raise levels of many drugs.","conf":"reported"}],"kind":"supp","supp":{"cat":"Metabolic and GLP-1 Support","does":"Counters possible GH-induced insulin resistance.","benefits":"In type 2 diabetes, berberine lowers fasting glucose about 0.6 mmol/L, post-meal glucose about 1.6 mmol/L, LDL and triglycerides about 0.3 mmol/L; vs placebo HbA1c fell about 0.7%, but trials are mostly small and low quality. Weight loss in pooled trials is about 2-3 kg over 2-3 months. Does not: work like 'nature's Ozempic'. GLP-1 drugs give about 10-15% body-weight loss over a year; berberine roughly one fifth of that, with no clinically shown effect on gastric emptying or brain appetite centres.","ev":"Moderate","evwhy":"2024 Frontiers meta-analysis of 50 RCTs (4,150 people), high heterogeneity, few low-bias trials; NCCIH 2023 on weight","warn":["GI effects are common: constipation, diarrhoea, gas, cramps, nausea, more at higher doses","Pregnancy and breastfeeding: do not use; crosses the placenta and into milk, can worsen newborn jaundice and cause kernicterus","Never give to infants"],"buy":["Label should state berberine HCl mg per capsule (often 500 mg) and source plant","Third-party tested; popularity has brought quality problems"],"dn":"With Tesamorelin. 500mg with Pancragen. Used with HGH above 4iu/day.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Poor bioavailability (under 1%); short half-life, so split with meals"}]}},{"slug":"s-cinnamon-extract","sid":"cinnamon-extract","name":"Cinnamon Extract","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1050,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Glucose","mid":"Organ","lt":"Organ","lb":"Organ"},"dots":[]},"canva":false,"primary":"Glucose","roles":["Glucose","Organ"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"500 mg-2 g/day","freq":"1-2x daily with meals","cycle":"","route":"Oral, Topical","half":"","use":"Small drops in fasting glucose and HbA1c; choose Ceylon or a water extract to dodge cassia coumarin","conf":"reported"},"desc":{},"syn":["Pancragen"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Small drops in fasting glucose and HbA1c; choose Ceylon or a water extract to dodge cassia coumarin","kw":["Metabolic and GLP-1 Support"],"whoNot":[{"t":"People with liver disease (cassia)","why":"Cassia cinnamon is rich in coumarin, which harms the liver at high intakes.","conf":"verified"},{"t":"People on hepatotoxic drugs (paracetamol, statins)","why":"Coumarin adds to the liver strain of other hepatotoxic drugs.","conf":"reported"},{"t":"People on diabetes medication","why":"It can lower blood sugar and add to diabetes drugs.","conf":"reported"}],"kind":"supp","supp":{"cat":"Metabolic and GLP-1 Support","does":"Paired with Pancragen, next to chromium and berberine on the blood sugar side of that stack.","benefits":"An umbrella review of 11 meta-analyses found fasting glucose about 11 mg/dL lower and HbA1c only about 0.1% lower in type 2 diabetes and PCOS, with high heterogeneity and unclear species. NCCIH calls the diabetes benefit unclear. Does not: replace glucose drugs, and more cassia is not better: coumarin limits how much you can safely take.","ev":"Limited","evwhy":"2023 umbrella meta-analysis (11 meta-analyses, 0.12-14.4 g/day); NCCIH says better studies needed","warn":["Cassia coumarin can injure the liver in sensitive people; avoid cassia supplements with liver disease","Ceylon in large amounts is considered unsafe in pregnancy; stick to food amounts","Hypoglycaemia risk when stacked with berberine, chromium or diabetes drugs"],"buy":["Species on label: Cinnamomum verum (Ceylon) or a cassia water extract; plain 'cinnamon' usually means cassia","Coumarin tested or stated 'coumarin reduced' for cassia extracts"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Capsules or food; cinnamaldehyde is well absorbed and quickly metabolised"},{"r":"Topical","note":"Cinnamon oil irritates skin and causes contact dermatitis"}]}},{"slug":"s-psyllium","sid":"psyllium","name":"Psyllium","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1051,"alias":"Psyllium husk, Ispaghula, Isabgol, Plantago ovata","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Gut","mid":"Heart","lt":"Glucose","lb":"Appetite"},"dots":[]},"canva":false,"primary":"Gut","roles":["Gut","Heart","Glucose","Appetite","Fat"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"5-10 g/day","freq":"1-3x daily with water","cycle":"","route":"Oral","half":"","use":"FDA heart claim: lowers LDL about 13 mg/dL; recommended for IBS; steadies blood sugar and stool","conf":"reported"},"desc":{},"syn":["Retatrutide + Cagrilintide","Amycretin","Liraglutide","MariTide","UBT-251"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"FDA heart claim: lowers LDL about 13 mg/dL; recommended for IBS; steadies blood sugar and stool","kw":["Metabolic and GLP-1 Support","Psyllium husk","Ispaghula","Isabgol","Plantago ovata"],"whoNot":[{"t":"People with swallowing difficulty or oesophageal narrowing","why":"Psyllium swells quickly; FDA requires a choking warning on dry forms.","conf":"verified"},{"t":"People who handle psyllium powder regularly","why":"Occupational allergy and anaphylaxis.","conf":"reported"},{"t":"People on lithium, carbamazepine or levothyroxine","why":"Psyllium binds these drugs in the gut and lowers absorption.","conf":"reported"}],"kind":"supp","supp":{"cat":"Metabolic and GLP-1 Support","does":"Gel-forming soluble fibre from Plantago ovata husk. It binds bile acids to lower LDL, slows sugar absorption, and normalises stool in both constipation and diarrhoea. The only fibre with an FDA heart health claim of its own.","benefits":"Lowers LDL cholesterol (about 13 mg/dL at about 10 g/day in a 28-trial meta-analysis, with similar falls in apoB), the basis of the 1998 FDA health claim. The ACG recommends psyllium, not wheat bran, for overall IBS symptoms. It improves constipation and modestly lowers fasting glucose and HbA1c in type 2 diabetes. Feeling full may help appetite control, but weight loss is small.","ev":"Strong","evwhy":"FDA health claim (21 CFR 101.81); Jovanovski 2018 AJCN meta-analysis, 28 RCTs; ACG IBS guideline","warn":["Choking and bowel obstruction if taken dry or with too little water; avoid with swallowing problems or bowel narrowing","Bloating and gas at first; start low and increase over weeks","Rare allergy, including in people who handle the powder (asthma)"],"buy":["Look for grams of soluble fibre per serving; at least 1.7 g for the heart claim","Husk purity 95% or more"],"dn":"","appr":"FDA OTC drug (monograph): Psyllium (husk, seed, hydrophilic mucilloid), OTC bulk-forming laxative","routes":[{"r":"Oral","note":"Powder stirred into a full glass of water and drunk at once, or capsules with water"}]}},{"slug":"s-lion-s-mane","sid":"lion-s-mane","name":"Lion's Mane","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1052,"alias":"lions mane, NGF","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Plasticity","mid":"Cognition","lt":"Cognition","lb":"Cognition"},"dots":[]},"canva":false,"primary":"Plasticity","roles":["Plasticity","Cognition"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"1-3 g/day","freq":"1-2x daily, with food","cycle":"","route":"Oral","half":"","use":"Edible mushroom studied for memory in mild cognitive impairment and for mood; small human trials, mixed results","conf":"reported"},"desc":{},"syn":["Cerebrolysin","Semax","Selank","Adamax","DSIP","PE-22-28","Cortagen","IllumiNeuro","Semax + Selank"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Edible mushroom studied for memory in mild cognitive impairment and for mood; small human trials, mixed results","kw":["Brain and Mood","lions mane","NGF"],"whoNot":[{"t":"People with mushroom allergy","why":"Skin and breathing allergic reactions have been reported.","conf":"reported"},{"t":"People on blood thinners","why":"Lion's mane may reduce platelet clumping and add to bleeding risk.","conf":"reported"},{"t":"People on diabetes medication","why":"It can lower blood sugar and add to diabetes drugs.","conf":"reported"}],"kind":"supp","supp":{"cat":"Brain and Mood","does":"NGF support. Paired with Semax, which works through BDNF, for a dual neurotrophic effect.","benefits":"Best signal is in older adults with mild cognitive impairment: about 3 g/day of fruiting body powder for 16 weeks improved cognitive scores, which fell back after stopping. Smaller trials report better mood, anxiety and sleep scores in overweight adults and menopausal women. In healthy young adults results are weak or null (no cognitive change over 4 weeks; a 2025 acute trial was inconclusive). It does not have human evidence for nerve regrowth or cancer; NGF and anti-tumour effects are cell and animal findings.","ev":"Limited","evwhy":"Handful of small RCTs (Mori 2009 MCI, Saitsu 2019, Vigna 2019, Li 2020, Docherty 2023); MSK rates human data as limited","warn":["Mild GI upset, nausea and skin rash reported in trials","Mushroom allergy: avoid if allergic to edible mushrooms; respiratory and skin reactions are reported","Pregnancy and breastfeeding: no safety data"],"buy":["Label should say 'fruiting body' in writing; 'mushroom' or 'full spectrum' alone usually means mycelium on grain","Ask for or look for a beta-glucan figure (fungal 1,3/1,6 beta-glucan assay), ideally 20%+ for fruiting body extracts, plus a starch figure under about 5%"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Capsule, powder or cooked mushroom; only route studied"}]}},{"slug":"s-bacopa-monnieri","sid":"bacopa-monnieri","name":"Bacopa Monnieri","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1053,"alias":"bacopa","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Cognition","mid":"Cognition","lt":"Cognition","lb":"Cognition"},"dots":[]},"canva":false,"primary":"Cognition","roles":["Cognition"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"300 mg/day","freq":"1x daily, with food","cycle":"","route":"Oral","half":"","use":"Ayurvedic herb with RCT support for memory free recall and attention speed after 8-12 weeks of daily use","conf":"reported"},"desc":{},"syn":["Semax","Selank","Adamax","DSIP","PE-22-28","IllumiNeuro","Semax + Selank"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Ayurvedic herb with RCT support for memory free recall and attention speed after 8-12 weeks of daily use","kw":["Brain and Mood","bacopa"],"whoNot":[{"t":"People with slow heart rate","why":"Bacopa raises acetylcholine signalling, which can slow the heart.","conf":"reported"},{"t":"People on thyroid medication","why":"Bacopa raised thyroid hormone (T4) in mice.","conf":"reported"},{"t":"People with stomach ulcers","why":"Cholinergic effects increase stomach secretions and cramping.","conf":"reported"}],"kind":"supp","supp":{"cat":"Brain and Mood","does":"Memory support.","benefits":"Across 12-week RCTs at 300-450 mg/day of standardised extract, Bacopa improves memory free recall (a 2012 review found gains on 9 of 17 memory tests) and speeds attention (a 2014 meta-analysis: faster Trail B and choice reaction time). Smaller trials report lower anxiety scores. Effects build slowly: expect nothing for the first few weeks, with most trials measuring at 12 weeks. It is not an acute focus aid and is not shown to treat dementia.","ev":"Moderate","evwhy":"Pase 2012 systematic review (6 RCTs) and Kongkeaw 2014 meta-analysis (9 RCTs, 437 analysed); small, short, mostly healthy adults","warn":["GI upset is the main side effect: nausea, cramps, more frequent stools; take with food","Fatigue or drowsiness reported in some users","Thyroid: raised T4 in animal studies; monitor if on thyroid medication or hyperthyroid"],"buy":["Label states bacoside percentage and method (HPLC preferred over UV, which overestimates)","Dose per serving reads about 300 mg extract"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Extract capsule with a meal; bacosides are fat-soluble and food reduces GI upset"}]}},{"slug":"s-phosphatidylserine","sid":"phosphatidylserine","name":"Phosphatidylserine","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1054,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Cognition","mid":"Cognition","lt":"Cognition","lb":"Cognition"},"dots":[]},"canva":false,"primary":"Cognition","roles":["Cognition"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"100-300 mg/day","freq":"1-3x daily, with meals","cycle":"","route":"Oral","half":"","use":"Membrane phospholipid with an FDA qualified claim for cognition in the elderly; best trials used the old bovine form","conf":"reported"},"desc":{},"syn":["Semax","Selank","Adamax","DSIP","PE-22-28","IllumiNeuro","Semax + Selank"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Membrane phospholipid with an FDA qualified claim for cognition in the elderly; best trials used the old bovine form","kw":["Brain and Mood"],"whoNot":[{"t":"People on anticholinergic drugs","why":"PS raises acetylcholine; opposes them.","conf":"inferred"},{"t":"People on blood thinners","why":"PS may have a mild blood-thinning effect that adds to these drugs.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Brain and Mood","does":"Cognitive support.","benefits":"The strongest positive memory trials in older adults (1990s) used bovine brain PS, withdrawn over mad cow risk. The modern soy and sunflower forms have weaker, mixed data: the best-designed soy trial (Jorissen 2001, 300-600 mg/day, 12 weeks) found no effect, while small Japanese trials and a marine PS-DHA trial show modest gains on some measures. At 400-800 mg/day it blunts cortisol after exercise or stress in small trials. It does not reverse dementia.","ev":"Limited","evwhy":"Bovine-era RCTs positive; soy-PS trials mixed; EFSA 2010 found no cause and effect; FDA allows only a qualified claim","warn":["GI upset and insomnia at higher doses (above about 300 mg); take earlier in the day","Soy-derived products: avoid with soy allergy","Pregnancy and breastfeeding: no safety data"],"buy":["Label shows mg of phosphatidylserine per serving, not mg of 'PS complex'","Source stated: sunflower or soy (soy allergy matters)"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Softgel or capsule with food; fat-soluble"}]}},{"slug":"s-magnesium-l-threonate","sid":"magnesium-l-threonate","name":"Magnesium L-Threonate","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1055,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Cognition","mid":"Sleep","lt":"Sleep","lb":"Sleep"},"dots":[]},"canva":false,"primary":"Cognition","roles":["Cognition","Sleep"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"1-2 g/day (salt)","freq":"1-2x daily, evening","cycle":"","route":"Oral","half":"","use":"Pricey magnesium salt marketed to raise brain magnesium; small industry-funded trials on memory and sleep","conf":"reported"},"desc":{},"syn":["Semax","Selank","Adamax","DSIP","PE-22-28","IllumiNeuro","Semax + Selank"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Pricey magnesium salt marketed to raise brain magnesium; small industry-funded trials on memory and sleep","kw":["Brain and Mood"],"whoNot":[{"t":"People with reduced kidney function","why":"Kidneys clear magnesium; build-up causes low blood pressure and weakness.","conf":"verified"},{"t":"People on bisphosphonates, quinolones or tetracyclines","why":"Magnesium binds these drugs in the gut; take them hours apart.","conf":"verified"}],"kind":"supp","supp":{"cat":"Brain and Mood","does":"Brain-targeted form of magnesium.","benefits":"In rats, threonate raised brain magnesium and synaptic density; in humans this has not been measured. Human data are small and industry-funded: 1.5-2 g/day for 12 weeks improved one executive-function test (Trail B) in 44 older adults, with no change in working memory, attention or episodic memory, and 1 g/day for 21 days improved sleep and daytime-function scores in 80 adults. It is a low-dose magnesium source: it will not correct deficiency efficiently.","ev":"Emerging","evwhy":"Liu 2016 (n=44) and Hausenblas 2024 (n=80), both funded by the ingredient maker; no independent replication or human brain-Mg data","warn":["Stacking with another magnesium (e.g. 2 g threonate plus 400 mg glycinate) takes supplemental Mg near 550 mg/day, above the 350 mg UL; watch for loose stools","Diarrhea, nausea, cramping at high supplemental magnesium","Kidney disease: magnesium can accumulate; avoid without supervision"],"buy":["Label: 2 g of magnesium L-threonate should show about 144 mg elemental magnesium; check both numbers","Count capsules: trial doses usually need 3-4 capsules a day"],"dn":"400mg of L-Threonate or Glycinate before bed with DSIP.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Only route; often split morning and 1-2 h before bed"}]}},{"slug":"s-alpha-gpc","sid":"alpha-gpc","name":"Alpha-GPC","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1056,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Cognition","mid":"Cognition","lt":"Cognition","lb":"Cognition"},"dots":[]},"canva":false,"primary":"Cognition","roles":["Cognition"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"300-600 mg/day","freq":"1-2x daily","cycle":"","route":"Oral, IM/IV","half":"","use":"Choline source (about 40% choline) used for focus and pre-workout power; a Rx dementia drug in parts of Europe and Asia","conf":"reported"},"desc":{},"syn":["Semax","Selank","Adamax","DSIP","PE-22-28","IllumiNeuro","Semax + Selank"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Choline source (about 40% choline) used for focus and pre-workout power; a Rx dementia drug in parts of Europe and Asia","kw":["Brain and Mood"],"whoNot":[{"t":"People with stroke risk factors","why":"Cohort: higher stroke risk with alpha-GPC.","conf":"reported"},{"t":"People with heart disease or high TMAO","why":"Gut bacteria turn choline into TMAO, linked to atherosclerosis.","conf":"reported"},{"t":"People on anticholinergic drugs","why":"It raises acetylcholine, directly opposing these drugs.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Brain and Mood","does":"Acetylcholine precursor.","benefits":"Alpha-GPC (choline alfoscerate) delivers choline that crosses into the brain. As a prescription drug, 1,200 mg/day improved cognitive scores in mild to moderate Alzheimer's over 6 months, and added modestly to donepezil. In trained men, a single 600 mg dose before exercise raised peak force or power in small trials. Evidence for focus in healthy young adults is thin. It does not prevent dementia.","ev":"Limited","evwhy":"Alzheimer's RCTs (De Jesus Moreno 2003; ASCOMALVA) at drug doses; small sports trials; no large trials in healthy adults","warn":["Observational stroke signal: in a 12-million-person Korean cohort, Alpha-GPC users had about 46% higher 10-year stroke risk (HR 1.46) with a dose-response; causation unproven, TMAO is the proposed link","Over 65 or with stroke or heart risk: weigh the stroke signal before long-term use","Headache, heartburn, insomnia, dizziness; fishy body odour at high choline intake"],"buy":["Check whether the label means 50% or 99% Alpha-GPC; mg of actual Alpha-GPC should be stated","Count total choline: add eggs, other supplements and prenatal choline against the 3,500 mg UL"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Capsule or powder; powder is hygroscopic"},{"r":"IM/IV","note":"Clinical only; used in Italy and Korea after stroke or for dementia as a prescription drug"}]}},{"slug":"s-l-theanine","sid":"l-theanine","name":"L-Theanine","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1057,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Mood","mid":"Mood","lt":"Mood","lb":"Mood"},"dots":[]},"canva":false,"primary":"Mood","roles":["Mood"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"100-400 mg/day","freq":"1-2x daily","cycle":"","route":"Oral","half":"","use":"Tea amino acid for calm focus without sedation; pairs with caffeine for attention, may improve sleep quality","conf":"reported"},"desc":{},"syn":["Selank","Semax + Selank"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Tea amino acid for calm focus without sedation; pairs with caffeine for attention, may improve sleep quality","kw":["Brain and Mood"],"whoNot":[{"t":"People on blood pressure medicines","why":"L-theanine can lower blood pressure slightly and add to BP drugs.","conf":"reported"},{"t":"People on sedatives","why":"Theanine adds to the calming effect of sedatives.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Brain and Mood","does":"Potentiates GABA, which works with Selank.","benefits":"Best evidence is for the caffeine combination: about 100-250 mg theanine with 40-150 mg caffeine improves attention switching and reduces caffeine jitter in acute trials. Alone, 200 mg/day for 4 weeks improved stress, sleep quality and some cognitive scores in healthy adults, and 400 mg/day improved actigraphy sleep efficiency in boys with ADHD. Effects are mild. It is not a sleeping pill and does not sedate.","ev":"Moderate","evwhy":"Multiple small acute RCTs with caffeine (Owen 2008, Giesbrecht 2010); Hidese 2019 4-week RCT; Lyon 2011 sleep trial; EFSA rejected claims in 2011","warn":["Mild: headache, dizziness, GI upset uncommon","May modestly lower blood pressure; add-on effect with antihypertensives","Pregnancy and breastfeeding: no data at supplement doses (tea in moderation is fine)"],"buy":["Label says L-theanine (not DL) with mg per capsule: 100 or 200 mg","For focus stacks, check caffeine mg too and keep about 2:1 theanine to caffeine"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Capsule, powder or tea; acts within 30-60 min"}]}},{"slug":"s-ashwagandha-ksm-66","sid":"ashwagandha-ksm-66","name":"Ashwagandha (KSM-66)","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1058,"alias":"KSM-66, stress","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Mood","mid":"Mood","lt":"Mood","lb":"Mood"},"dots":[]},"canva":false,"primary":"Mood","roles":["Mood"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"300-600 mg/day","freq":"1-2x daily, with food","cycle":"","route":"Oral","half":"","use":"Best-evidenced adaptogen: lowers perceived stress and cortisol, modestly improves sleep; liver and thyroid flags","conf":"reported"},"desc":{},"syn":["Selank","Semax + Selank"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Best-evidenced adaptogen: lowers perceived stress and cortisol, modestly improves sleep; liver and thyroid flags","kw":["Brain and Mood","KSM-66","stress"],"whoNot":[{"t":"People with hyperthyroidism or on thyroid hormone","why":"Raises thyroid hormone; thyrotoxicosis reported.","conf":"reported"},{"t":"Men with hormone-sensitive prostate cancer","why":"Ashwagandha raises testosterone, which feeds hormone-sensitive prostate cancer.","conf":"verified"},{"t":"People with autoimmune disease","why":"Ashwagandha stimulates immune activity and may flare autoimmune disease.","conf":"reported"},{"t":"People with liver disease","why":"Dozens of liver injury cases are documented, some severe.","conf":"reported"}],"kind":"supp","supp":{"cat":"Brain and Mood","does":"Cortisol reduction.","benefits":"Root extract at 250-600 mg/day for 6-12 weeks lowers perceived stress and anxiety scores and morning cortisol in multiple small RCTs, nearly all from India; benefits look larger at 500-600 mg/day. A 2021 meta-analysis (5 RCTs, 372 adults) found a small sleep benefit, larger at 600 mg/day, after 8+ weeks and in insomnia. It may raise testosterone and thyroid hormones. It is not a treatment for diagnosed anxiety disorders; guidelines give only a provisional recommendation.","ev":"Moderate","evwhy":"About 12 RCTs (1,002 adults) on stress; Cheah 2021 sleep meta-analysis; short, small, mostly Indian, often supplier-funded","warn":["Liver injury: rare cholestatic hepatitis with jaundice and itching after 2-12 weeks, usually resolving after stopping; LiverTox lists it as a probable rare cause","Thyroid: raises T3/T4 and can cause thyrotoxicosis; avoid with hyperthyroidism","Pregnancy: avoid (possible abortifacient; Australia requires a pregnancy warning; France advises against); avoid while breastfeeding"],"buy":["Label says root only and gives withanolide % (about 5% for KSM-66 type)","Dose per serving reads 300 mg (or 600 mg total per day)"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Capsule or powder with food; only route used"}]}},{"slug":"s-taurine","sid":"taurine","name":"Taurine","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1059,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Mood","mid":"Mood","lt":"Mood","lb":"Mood"},"dots":[]},"canva":false,"primary":"Mood","roles":["Mood"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"1-3 g/day","freq":"1-2x daily","cycle":"","route":"Oral, IV","half":"","use":"Abundant amino acid in heart, muscle and brain; ageing headlines from mice, modest blood pressure and exercise data","conf":"reported"},"desc":{},"syn":["Selank","Semax + Selank"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Abundant amino acid in heart, muscle and brain; ageing headlines from mice, modest blood pressure and exercise data","kw":["Brain and Mood"],"whoNot":[{"t":"People with leukaemia","why":"Taurine fuels leukaemia stem cells in a 2024 Nature study.","conf":"reported"},{"t":"People on blood pressure medicines","why":"Taurine lowers blood pressure modestly and can add to BP drugs.","conf":"reported"}],"kind":"supp","supp":{"cat":"Brain and Mood","does":"GABA-A co-agonist.","benefits":"In humans, 1-6 g/day modestly lowers blood pressure in pooled trials and gives a small endurance benefit; in Japan it is an approved drug for heart failure at 3 g/day. A 2023 Science paper found taurine supplements extended mouse lifespan by 10-12% and improved health markers in monkeys, and proposed taurine decline as a driver of ageing. A 2025 Science follow-up found blood taurine does not reliably fall with age in humans, monkeys or mice, so it is not a validated ageing marker or proven longevity agent. Human evidence for anxiety or GABA effects is weak.","ev":"Limited","evwhy":"Small BP and exercise trials and meta-analyses; ageing data are animal (Singh 2023) and contested (Fernandez 2025)","warn":["Generally well tolerated up to 3 g/day; GI upset at higher doses","Blood cancers: a 2024 mouse study found marrow taurine fuelled myeloid leukaemia growth; avoid supplementing with leukaemia or MDS until clarified","Bipolar disorder on lithium: taurine may alter lithium handling (case-level evidence)"],"buy":["Pure taurine, mg per serving stated; 1 level teaspoon is about 2-3 g, so weigh or use capsules","Synthetic taurine is standard and vegan; 'natural' sources add nothing"],"dn":"","appr":"In the US, only as one ingredient of IV paediatric nutrition.","routes":[{"r":"Oral","note":"Powder or capsule; water soluble, taste neutral"},{"r":"IV","note":"Clinical only, in parenteral nutrition for infants and long-term IV feeding"}]}},{"slug":"s-curcumin","sid":"curcumin","name":"Curcumin","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1060,"alias":"turmeric","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Inflammation","mid":"Inflammation","lt":"Inflammation","lb":"Inflammation"},"dots":[]},"canva":false,"primary":"Inflammation","roles":["Inflammation"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"500-1,000 mg/day","freq":"1-2x daily, with food","cycle":"","route":"Oral, Topical / mouthwash","half":"","use":"Modest knee osteoarthritis pain relief in trials; enhanced-absorption forms carry a rare idiosyncratic liver injury risk","conf":"reported"},"desc":{},"syn":["KPV","GHK-Cu + KPV","KLOW","Tri-HealMax"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Modest knee osteoarthritis pain relief in trials; enhanced-absorption forms carry a rare idiosyncratic liver injury risk","kw":["Immune, Gut and Inflammation","turmeric"],"whoNot":[{"t":"People with gallstones or bile duct blockage","why":"Curcumin makes the gallbladder contract, which can provoke pain with stones.","conf":"reported"},{"t":"People with iron deficiency","why":"Curcumin binds iron and can deepen iron deficiency.","conf":"reported"},{"t":"People taking piperine-boosted products with liver risk","why":"Liver injury clusters linked to high-bioavailability turmeric.","conf":"reported"},{"t":"People on tacrolimus or blood thinners","why":"Piperine raises tacrolimus levels; curcumin adds to bleeding risk.","conf":"reported"}],"kind":"supp","supp":{"cat":"Immune, Gut and Inflammation","does":"Additional NF-kB inhibition alongside KPV.","benefits":"Best evidence is for knee osteoarthritis: 10 RCTs (1,287 people) showed less pain and better function versus placebo, and 3 small trials found it similar to ibuprofen or diclofenac with fewer GI side effects. Early, inconsistent signals for fatty liver and chemotherapy mouth sores. NCCIH says there is not enough evidence to conclude it helps any condition. It does not cure inflammatory disease or cancer, and plain turmeric powder is barely absorbed.","ev":"Moderate","evwhy":"Knee OA only: 2021 systematic review of 10 RCTs (BMJ Open Sport Exerc Med); small, short trials with mixed proprietary formulations. Limited elsewhere.","warn":["Liver injury: LiverTox likelihood A, hepatocellular, usually 1-4 months after starting; HLA-B*35:01 in over 70% of cases. Stop at dark urine, jaundice, fatigue or nausea.","Avoid with existing or past liver disease, gallstones or bile duct obstruction (Italy, France, Australia and Canada warnings).","Pregnancy: supplement doses may be unsafe (NCCIH); Italy requires a no-use label in pregnancy and breastfeeding."],"buy":["Label should state mg of curcuminoids (not just turmeric root) and the standardisation, e.g. 95% curcuminoids.","Check whether piperine or an absorption enhancer is added; if so, the effective dose is several times higher than the number suggests."],"dn":"Longvida or Meriva forms.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Main route; native curcumin is poorly absorbed and quickly conjugated, which is why enhanced forms exist."},{"r":"Topical / mouthwash","note":"Used for oral mucositis in early trials; skin ointment effect on knee pain unclear; can cause hives."}]}},{"slug":"s-l-glutamine","sid":"l-glutamine","name":"L-Glutamine","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1061,"alias":"glutamine, gut","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Gut","mid":"Gut","lt":"Gut","lb":"Gut"},"dots":[]},"canva":false,"primary":"Gut","roles":["Gut"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"5 g/day","freq":"1-3x daily","cycle":"","route":"Oral, IV / enteral","half":"","use":"FDA-approved drug form cuts sickle cell crises; one trial in post-infectious IBS; gut-barrier hype outruns the data","conf":"reported"},"desc":{},"syn":["KPV","GHK-Cu + KPV","KLOW","Tri-HealMax"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"FDA-approved drug form cuts sickle cell crises; one trial in post-infectious IBS; gut-barrier hype outruns the data","kw":["Immune, Gut and Inflammation","glutamine","gut"],"whoNot":[{"t":"People with cirrhosis or hepatic encephalopathy","why":"Glutamine breaks down to ammonia, which a failing liver cannot clear.","conf":"reported"},{"t":"People with active cancer","why":"Many tumours use glutamine as a main fuel.","conf":"inferred"},{"t":"People with bipolar disorder","why":"Case reports describe mania in people with bipolar disorder.","conf":"reported"}],"kind":"supp","supp":{"cat":"Immune, Gut and Inflammation","does":"Fuel for intestinal epithelial cells.","benefits":"Strongest evidence is a prescription L-glutamine powder that reduced sickle cell pain crises and hospitalisations (FDA 2017). One RCT in post-infectious diarrhoea-predominant IBS with leaky gut found 5 g three times daily improved symptoms and permeability. Claims that it heals 'leaky gut' in general, builds muscle or speeds recovery in healthy people are not supported; the body makes plenty and food supplies 3-6 g/day.","ev":"Limited","evwhy":"Strong only for sickle cell (drug trial, n=230). Gut: one single-centre RCT (Gut 2019, n=115, not ITT). Critical-illness trials (REDOXS) showed harm at high IV/enteral doses.","warn":["Avoid in liver cirrhosis or hepatic encephalopathy: glutamine is metabolised to ammonia.","Avoid in severe kidney disease; dose is a nitrogen load.","Critically ill patients with multi-organ failure: high-dose glutamine raised mortality (REDOXS)."],"buy":["Label should read L-glutamine, about 5 g per scoop, with no proprietary blend.","Fermentation-derived, unflavoured powder is the cleanest; check third-party testing."],"dn":"","appr":"FDA-approved as: L-glutamine oral powder, Rx, sickle cell disease complications (also short bowel syndrome)","routes":[{"r":"Oral","note":"Powder in a cold or room-temperature drink; heat degrades it."},{"r":"IV / enteral","note":"Clinical only, in parenteral nutrition; high doses in critically ill patients with organ failure increased mortality (REDOXS 2013)."}]}},{"slug":"s-probiotics","sid":"probiotics","name":"Probiotics","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1062,"alias":"gut","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Gut","mid":"Immunity","lt":"Immunity","lb":"Immunity"},"dots":[]},"canva":false,"primary":"Gut","roles":["Gut","Immunity"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"5-40 billion CFU/day","freq":"daily, on antibiotics","cycle":"","route":"Oral, Vaginal","half":"","use":"Specific strains cut antibiotic diarrhoea and C. difficile risk; most other uses are strain-dependent or unproven","conf":"reported"},"desc":{},"syn":["KPV","LL-37","Selank","GHK-Cu + KPV","KLOW","Semax + Selank","Tri-HealMax"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Specific strains cut antibiotic diarrhoea and C. difficile risk; most other uses are strain-dependent or unproven","kw":["Immune, Gut and Inflammation","gut"],"whoNot":[{"t":"People with acute pancreatitis","why":"PROPATRIA trial: more deaths with probiotics.","conf":"reported"},{"t":"People with a central line or severe immunosuppression","why":"Bloodstream infections from probiotic strains.","conf":"verified"},{"t":"Premature infants","why":"FDA warned after a fatal infection in a preterm baby.","conf":"verified"},{"t":"People with short bowel syndrome","why":"Bacteria in a shortened gut can produce D-lactic acid, causing confusion.","conf":"reported"}],"kind":"supp","supp":{"cat":"Immune, Gut and Inflammation","does":"Gut and gut-brain axis support. LL-37 disrupts beneficial bacteria too, so probiotics are taken apart from it.","benefits":"Best evidence: preventing antibiotic-associated diarrhoea (children 8% vs 19%, Cochrane) and C. difficile diarrhoea (1.5% vs 4.0%, about 60% relative cut, strongest when baseline risk is above 5%). The evidence is strain-specific: L. rhamnosus GG and S. boulardii carry most of it. The AGA 2020 guideline recommends against probiotics for most GI conditions, including acute diarrhoea in children, and makes no recommendation for IBS. They do not 'reset' the microbiome in healthy people and most strains do not colonise.","ev":"Moderate","evwhy":"Cochrane C. difficile review (31 RCTs, 8,672 people, moderate certainty) and Cochrane paediatric AAD review (23 RCTs, 3,938 children); AGA 2020 only conditional and only for named strain sets.","warn":["Immunocompromised, critically ill, or anyone with a central venous line: rare bacteraemia and fungaemia.","Preterm infants: FDA 2023 warning after a fatal sepsis from a live Bifidobacterium product in a NICU infant under 1,000 g.","Severe acute pancreatitis: the probiotic arm had higher mortality in the PROPATRIA trial (2008)."],"buy":["Strain codes printed (genus, species and strain, e.g. L. rhamnosus GG).","CFU guaranteed through expiry date, not at manufacture."],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Take with or just after food; during antibiotics, space 2 h from the antibiotic dose (bacterial strains only)."},{"r":"Vaginal","note":"Lactobacillus products for bacterial vaginosis; evidence weak."}]}},{"slug":"s-saccharomyces-boulardii","sid":"saccharomyces-boulardii","name":"Saccharomyces boulardii","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1063,"alias":"S. boulardii, yeast probiotic","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Gut","mid":"Gut","lt":"Gut","lb":"Gut"},"dots":[]},"canva":false,"primary":"Gut","roles":["Gut"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"250-500 mg (5-10B CFU)","freq":"1-2x daily","cycle":"","route":"Oral","half":"","use":"Probiotic yeast that halves antibiotic diarrhoea risk and survives antibiotics; rare fungaemia with central lines","conf":"reported"},"desc":{},"syn":["LL-37"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Probiotic yeast that halves antibiotic diarrhoea risk and survives antibiotics; rare fungaemia with central lines","kw":["Immune, Gut and Inflammation","S. boulardii","yeast probiotic"],"whoNot":[{"t":"People with a central line or in intensive care","why":"Fungaemia, even in neighbouring patients.","conf":"reported"},{"t":"People taking antifungals","why":"Antifungals kill the yeast, so it will not work.","conf":"inferred"},{"t":"People with yeast allergy","why":"People allergic to yeast can react to it.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Immune, Gut and Inflammation","does":"Yeast probiotic that LL-37 does not touch.","benefits":"A 2015 meta-analysis of 21 RCTs (4,780 people) found it cut antibiotic-associated diarrhoea from 17.4% to 8.2% in adults and 20.9% to 8.8% in children; C. difficile diarrhoea benefit was shown only in children. As a yeast it is not killed by antibiotics, so it can be taken alongside them. It is also used for acute infectious diarrhoea in children and as an add-on to H. pylori eradication to reduce side effects. It does not treat established C. difficile on its own.","ev":"Moderate","evwhy":"Szajewska 2015 meta-analysis (21 RCTs); contributes to Cochrane AAD and C. difficile reviews; strain CNCM I-745 carries most data.","warn":["Fungaemia: rare, mostly in critically ill, immunocompromised and central venous catheter patients; EMA review counted 61 cases, 10 fatal. Avoid in these groups.","Not with systemic or oral antifungals: they kill the yeast.","Yeast allergy: avoid."],"buy":["Strain code on the label (CNCM I-745 is the most studied).","Dose in mg and CFU, guaranteed at expiry."],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Capsule or sachet; can be taken at the same time as antibiotics. Do not open sachets or capsules near patients with central lines (airborne contamination of catheters)."}]}},{"slug":"s-lactoferrin","sid":"lactoferrin","name":"Lactoferrin","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1064,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Immunity","mid":"Gut","lt":"Gut","lb":"Gut"},"dots":[]},"canva":false,"primary":"Immunity","roles":["Immunity","Gut"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"200-500 mg/day","freq":"1-2x daily","cycle":"","route":"Oral, Enteral (neonatal)","half":"","use":"Iron-binding milk protein; helps iron-deficiency anaemia in pregnancy trials; failed in large preterm infection trial","conf":"reported"},"desc":{},"syn":["LL-37"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Iron-binding milk protein; helps iron-deficiency anaemia in pregnancy trials; failed in large preterm infection trial","kw":["Immune, Gut and Inflammation"],"whoNot":[{"t":"People with cow's milk protein allergy","why":"Most lactoferrin is purified from cow's milk.","conf":"reported"}],"kind":"supp","supp":{"cat":"Immune, Gut and Inflammation","does":"Paired with LL-37 in its gut and biofilm stack.","benefits":"Most consistent evidence is for iron-deficiency anaemia in pregnancy, where small trials found bovine lactoferrin raised haemoglobin and ferritin at least as well as ferrous salts with fewer GI effects. For preventing colds and respiratory infections, evidence is a handful of small, mostly Japanese and Italian trials with modest signals. The large UK ELFIN trial (2,203 very preterm babies) found no reduction in late-onset infection, and a hospital COVID-19 trial was also null. It does not replace iron when deficiency is severe.","ev":"Limited","evwhy":"Null in the largest trial (ELFIN, Lancet 2019); anaemia-in-pregnancy meta-analysis and respiratory trials are small and heterogeneous.","warn":["Milk-protein allergy: avoid (lactose content is negligible but protein is the allergen).","Mild GI upset, constipation, rash at high doses.","Pregnancy: used in anaemia trials without safety signals, but data are small."],"buy":["Purity on the label (90%+ lactoferrin) and mg of lactoferrin per capsule.","Bovine source; avoid if milk-protein allergic."],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Best on an empty stomach or between meals; partly digested by stomach acid."},{"r":"Enteral (neonatal)","note":"Clinical only; preterm use not supported after ELFIN."}]}},{"slug":"s-elderberry","sid":"elderberry","name":"Elderberry","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1065,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Immunity","mid":"Immunity","lt":"Immunity","lb":"Immunity"},"dots":[]},"canva":false,"primary":"Immunity","roles":["Immunity"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"600-900 mg extract/day","freq":"2-4x daily, 3-5 days","cycle":"","route":"Oral","half":"","use":"Cooked black elderberry extract may shorten cold and flu symptoms in small trials; raw berries and leaves are toxic","conf":"reported"},"desc":{},"syn":["Glutathione","Thymosin Alpha-1","Thymalin"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Cooked black elderberry extract may shorten cold and flu symptoms in small trials; raw berries and leaves are toxic","kw":["Immune, Gut and Inflammation"],"whoNot":[{"t":"People making syrup from raw or unripe berries","why":"Raw or unripe berries, leaves and stems contain cyanide-producing compounds.","conf":"verified"},{"t":"People with autoimmune disease or on immunosuppressants","why":"It stimulates immune activity, which works against immunosuppressants.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Immune, Gut and Inflammation","does":"Listed as antiviral support in the immune phase.","benefits":"Small RCTs (about 180 people pooled in a 2019 meta-analysis) suggested shorter, milder colds and flu, including in air travellers. A 2020 ED trial in confirmed influenza found no benefit and slightly longer symptoms in some patients. No good evidence for COVID-19 (FDA and FTC acted on claims). It is not a flu vaccine or antiviral substitute.","ev":"Limited","evwhy":"Hawkins 2019 meta-analysis (180 participants, small, industry-linked trials) vs null Macknin 2020 RCT (n=87).","warn":["Raw or unripe fruit, leaves and stems are poisonous; only cooked or commercial extract.","Cytokine question: lab data show it raises inflammatory cytokines; whether this matters in severe infection is unknown, so many clinicians stop it once severe symptoms start (inferred, unproven).","Autoimmune disease: theoretical immune stimulation."],"buy":["Species on label: Sambucus nigra (black elder) fruit.","Extract amount in mg and anthocyanin standardisation, not just 'elderberry juice'."],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Syrup, lozenge, capsule; start within 48 h of symptoms in the trials."}]}},{"slug":"s-mushroom-complex","sid":"mushroom-complex","name":"Mushroom Complex","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1066,"alias":"reishi, chaga, turkey tail","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Immunity","mid":"Immunity","lt":"Immunity","lb":"Immunity"},"dots":[]},"canva":false,"primary":"Immunity","roles":["Immunity"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"1-3 g extract/day","freq":"1-2x daily","cycle":"","route":"Oral","half":"","use":"Reishi, chaga and turkey tail beta-glucans; turkey tail PSK is a cancer adjunct in Japan; chaga can damage kidneys","conf":"reported"},"desc":{},"syn":["Glutathione","Thymosin Alpha-1","Thymalin"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Reishi, chaga and turkey tail beta-glucans; turkey tail PSK is a cancer adjunct in Japan; chaga can damage kidneys","kw":["Immune, Gut and Inflammation","reishi","chaga","turkey tail"],"whoNot":[{"t":"Transplant recipients on anti-rejection drugs","why":"Mushroom beta-glucans stimulate immunity, which works against anti-rejection drugs.","conf":"reported"},{"t":"People on blood thinners (reishi)","why":"Reishi reduces platelet clumping and adds to bleeding risk.","conf":"reported"},{"t":"People with liver disease (reishi)","why":"Dozens of liver injury cases are documented, some severe.","conf":"reported"}],"kind":"supp","supp":{"cat":"Immune, Gut and Inflammation","does":"Innate immunity support through beta-glucans.","benefits":"Turkey tail's PSK extract is used in Japan as an adjunct after surgery and chemotherapy, with trials suggesting better survival in gastric and colorectal cancer. Reishi shows immune-marker changes but a Cochrane review found no significant tumour response. Chaga evidence is lab and animal only. None of these replace cancer treatment, and 'immune boosting' in healthy people is unproven.","ev":"Limited","evwhy":"PSK adjuvant trials in Japan (moderate, regional); Cochrane 2016 reishi null on tumour response; chaga preclinical only.","warn":["Chaga: oxalate nephropathy; a man on 3-9 g/day for about 5 years needed lifelong dialysis. Avoid with kidney disease or oxalate stones.","Reishi: case reports of hepatitis, including a fatal one with reishi powder; stop at jaundice.","Bleeding risk: reishi and chaga may inhibit platelets."],"buy":["Beta-glucan percentage measured with a mushroom-specific (1-3),(1-6)-beta-glucan assay, and starch or alpha-glucan below about 5%.","'Fruiting body' stated; 'myceliated grain' or 'full spectrum' usually means grain."],"dn":"Reishi, Chaga and Turkey Tail.","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Hot-water extracts release beta-glucans; raw powders are poorly digested."}]}},{"slug":"s-astragalus","sid":"astragalus","name":"Astragalus","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1067,"alias":"","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Immunity","mid":"Immunity","lt":"Immunity","lb":"Immunity"},"dots":[]},"canva":false,"primary":"Immunity","roles":["Immunity"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"500 mg-2 g extract/day","freq":"1-2x daily","cycle":"","route":"Oral, IV","half":"","use":"TCM root with immune-marker effects in small trials; avoid with autoimmune disease or immunosuppressants","conf":"reported"},"desc":{},"syn":["Thymosin Alpha-1","Thymalin"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"TCM root with immune-marker effects in small trials; avoid with autoimmune disease or immunosuppressants","kw":["Immune, Gut and Inflammation"],"whoNot":[{"t":"Transplant recipients on anti-rejection drugs","why":"It stimulates immune activity, which works against immunosuppressants.","conf":"reported"},{"t":"People with lupus, MS or rheumatoid arthritis","why":"It stimulates immune activity, which works against immunosuppressants.","conf":"reported"},{"t":"People on lithium","why":"Astragalus has a diuretic effect that may raise lithium levels.","conf":"reported"}],"kind":"supp","supp":{"cat":"Immune, Gut and Inflammation","does":"Part of the Thymosin Alpha-1 immune stack.","benefits":"Used for centuries in Chinese medicine, usually in combinations. Reviews of small, mostly Chinese studies report raised immune markers and lower inflammatory cytokines (2023), better HbA1c when added to metformin (2024), and kidney markers in membranous nephropathy, but quality is low. NCCIH says evidence is not sufficient for any condition. The telomerase activator cycloastragenol is a separate compound; astragalus root does not deliver meaningful amounts.","ev":"Traditional","evwhy":"NCCIH: insufficient reliable evidence; 2023-2024 reviews of 19-50 small, low-quality trials.","warn":["Autoimmune disease (lupus, RA, MS): may worsen symptoms; avoid (NCCIH).","Transplant or immunosuppressed patients: may oppose therapy.","Pregnancy: animal data show fetal toxicity; avoid."],"buy":["Species and plant part: Astragalus membranaceus (or mongholicus) root.","Standardisation stated (e.g. polysaccharides % or astragaloside IV %)."],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Root decoction, powder or extract."},{"r":"IV","note":"Clinical only; used in China, not approved elsewhere, and linked to allergic reactions."}]}},{"slug":"s-cranberry","sid":"cranberry","name":"Cranberry","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1068,"alias":"Vaccinium macrocarpon, Cranberry PAC, Proanthocyanidins, Cranberry extract","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Organ","mid":"Immunity","lt":"Reproductive","lb":"Reproductive"},"dots":[]},"canva":false,"primary":"Organ","roles":["Organ","Immunity","Reproductive"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"36 mg PAC/day","freq":"Daily, ongoing","cycle":"","route":"Oral","half":"","use":"Cochrane 2023: cuts symptomatic UTIs about 30%, including recurrent UTI in women. Prevention only","conf":"reported"},"desc":{},"syn":[],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Cochrane 2023: cuts symptomatic UTIs about 30%, including recurrent UTI in women. Prevention only","kw":["Immune, Gut and Inflammation","Vaccinium macrocarpon","Cranberry PAC","Proanthocyanidins","Cranberry extract"],"whoNot":[{"t":"People on warfarin","why":"Case reports show INR rises and bleeding on warfarin.","conf":"reported"},{"t":"People with oxalate kidney stones","why":"Concentrated cranberry products raise urine oxalate.","conf":"reported"},{"t":"People with aspirin allergy","why":"Cranberry contains salicylic acid, the aspirin relative.","conf":"reported"}],"kind":"supp","supp":{"cat":"Immune, Gut and Inflammation","does":"Cranberry proanthocyanidins (PACs) stop certain E. coli strains sticking to the bladder wall. Daily use lowers the chance of symptomatic urinary tract infections in women with recurrent UTI, children and people after bladder procedures. It does not treat an active infection.","benefits":"Cochrane 2023 (50 RCTs, 8,857 people) found cranberry products reduce symptomatic, culture-confirmed UTIs (RR 0.70, moderate certainty), including in women with recurrent UTI (RR 0.74), children (RR 0.46) and after bladder interventions (RR 0.47). No benefit in pregnancy, institutionalised older adults or people with neurogenic bladder. It does not treat an existing UTI; that needs antibiotics.","ev":"Strong","evwhy":"Cochrane 2023 review, 50 RCTs, moderate certainty for prevention; no evidence for treatment","warn":["Not a treatment: fever, flank pain or blood in urine needs medical care and antibiotics","No benefit shown in pregnancy, elderly care home residents or neurogenic bladder","GI upset is the main side effect, similar to placebo"],"buy":["Label should state mg PAC per serving and the method (BL-DMAC); 36 mg is the reference","'500 mg cranberry' without PAC content tells you little"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Capsules or unsweetened juice; juice and tablets not clearly different (very low certainty)"}]}},{"slug":"s-beet-root","sid":"beet-root","name":"Beet Root","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1069,"alias":"beetroot, nitric oxide","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Heart","mid":"Heart","lt":"Heart","lb":"Heart"},"dots":[]},"canva":false,"primary":"Heart","roles":["Heart"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"6-8 mmol nitrate","freq":"2-3 h pre-exercise","cycle":"","route":"Oral","half":"","use":"Dietary nitrate improves 4-30 min endurance and power efforts and lowers blood pressure; antiseptic mouthwash blocks it","conf":"reported"},"desc":{},"syn":["Vesugen"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Dietary nitrate improves 4-30 min endurance and power efforts and lowers blood pressure; antiseptic mouthwash blocks it","kw":["Vascular","beetroot","nitric oxide"],"whoNot":[{"t":"People with oxalate kidney stones","why":"Beets are among the highest-oxalate foods.","conf":"reported"},{"t":"People using antiseptic mouthwash daily","why":"Kills mouth bacteria needed to convert nitrate.","conf":"reported"},{"t":"People doing stool or urine blood tests","why":"Red beet pigment in urine or stool can look like blood.","conf":"reported"},{"t":"People on PDE5 inhibitors or nitrates","why":"Nitrate raises nitric oxide; with these drugs pressure can drop too far.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Vascular","does":"Nitric oxide support, listed with Vesugen.","benefits":"Nitrate (not the beet itself) is converted by mouth bacteria to nitrite and then nitric oxide, improving muscle efficiency. The IOC and AIS rate it as an evidence-based performance supplement for efforts of about 4-30 minutes, team sports and sprints; benefit shrinks in highly trained athletes (VO2max above 65). It lowers blood pressure, more clearly in older adults. Powders without stated nitrate often contain almost none.","ev":"Strong","evwhy":"IOC 2018 consensus and AIS Group A; many RCTs. BP effect consistent but modest.","warn":["Antiseptic mouthwash (chlorhexidine) blunts the nitrite rise; avoid around dosing.","Beeturia: pink or red urine and stools are harmless (but rule out blood if unsure).","Oxalate-rich: caution with calcium oxalate kidney stones."],"buy":["Nitrate per serving in mmol or mg (at least 5-6 mmol for performance).","Sugar content in juices."],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Must pass through the mouth: oral bacteria reduce nitrate to nitrite. Capsules swallowed whole still work via saliva recirculation, but mouthwash blocks it."}]}},{"slug":"s-citrulline","sid":"citrulline","name":"Citrulline","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1070,"alias":"L-citrulline, nitric oxide","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Heart","mid":"Heart","lt":"Heart","lb":"Heart"},"dots":[]},"canva":false,"primary":"Heart","roles":["Heart"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"3-6 g L-cit / 6-8 g malate","freq":"1 h pre-workout","cycle":"","route":"Oral","half":"","use":"Raises arginine and nitric oxide better than arginine itself; mixed, small effects on reps and fatigue","conf":"reported"},"desc":{},"syn":["Vesugen"],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Raises arginine and nitric oxide better than arginine itself; mixed, small effects on reps and fatigue","kw":["Vascular","L-citrulline","nitric oxide"],"whoNot":[{"t":"People on PDE5 inhibitors or nitrates","why":"Nitrate raises nitric oxide; with these drugs pressure can drop too far.","conf":"inferred"},{"t":"People prone to herpes outbreaks","why":"Citrulline converts to arginine, which herpes viruses use to replicate.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Vascular","does":"Nitric oxide support, listed with Vesugen.","benefits":"Oral citrulline raises plasma arginine more reliably than oral arginine because it bypasses gut and liver breakdown. Performance trials are mixed: some show more reps and less soreness with 8 g citrulline malate, but a 2023 RCT of 8 g L-citrulline found no effect on strength, endurance or muscle oxygenation. Small studies show modest BP and erectile function effects. It is not a reliable strength booster.","ev":"Limited","evwhy":"Mixed RCTs; listed as 'mixed' for strength in the report; Gonzalez 2023 null at 8 g L-citrulline.","warn":["Mild GI upset at higher doses.","Low blood pressure or on BP drugs: additive effect.","Pregnancy and breastfeeding: not enough data."],"buy":["Check whether the number is L-citrulline or citrulline malate, and the ratio.","For performance, the scoop should give 6-8 g citrulline malate or 3-6 g L-citrulline."],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Powder in water; splitting the daily dose may improve conversion to arginine (2025 PK study)."}]}},{"slug":"s-plant-sterols","sid":"plant-sterols","name":"Plant Sterols","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1071,"alias":"Phytosterols, Plant stanols, Stanol esters, Sterol esters, Beta-sitosterol","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Heart","mid":"Fat","lt":"Fat","lb":"Fat"},"dots":[]},"canva":false,"primary":"Heart","roles":["Heart","Fat"],"reported":[],"fda":true,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"1.5-3 g/day","freq":"With main meals","cycle":"","route":"Oral","half":"","use":"Lowers LDL about 6-12% at 0.6-3.3 g/day, add-on to diet or statins. No event outcome data","conf":"reported"},"desc":{},"syn":[],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Lowers LDL about 6-12% at 0.6-3.3 g/day, add-on to diet or statins. No event outcome data","kw":["Vascular","Phytosterols","Plant stanols","Stanol esters","Sterol esters","Beta-sitosterol"],"whoNot":[{"t":"People with sitosterolaemia","why":"An inherited disorder where plant sterols are absorbed and cause early heart disease.","conf":"verified"},{"t":"People who do not need cholesterol lowering","why":"EU law requires the label to say it is not for people who do not need to lower cholesterol.","conf":"verified"},{"t":"People with low carotenoid status","why":"Sterols lower blood beta-carotene and other carotenoids.","conf":"reported"}],"kind":"supp","supp":{"cat":"Vascular","does":"Plant compounds shaped like cholesterol that compete with it for absorption in the gut. About 2 g a day with meals lowers LDL by roughly 8-10%. No trial has shown fewer heart attacks or strokes.","benefits":"Lowers LDL cholesterol in a dose-dependent way, about 6% to 12% across 0.6-3.3 g/day and plateauing near 3 g (Ras 2014, 124 trials); sterols and stanols perform alike. The effect adds to statins. There are no trials showing fewer cardiovascular events, so it is an LDL tool, not a proven heart attack preventer.","ev":"Strong","evwhy":"Strong for LDL lowering (meta-analysis of 124 RCTs); no hard-outcome RCTs","warn":["Sitosterolaemia (rare genetic disorder): contraindicated","Lowers blood beta-carotene and other carotenoids; eat fruit and vegetables daily","EU labels: not for people who do not need to lower cholesterol, and may not suit pregnancy, breastfeeding or children under 5"],"buy":["Check grams of plant sterols or stanols per serving; you need 1.5-3 g total daily","Ester weight is not free sterol weight; look for the 'equivalent to X g sterols' line"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Must be taken with meals containing fat to reach cholesterol in the gut"}]}},{"slug":"s-caffeine","sid":"caffeine","name":"Caffeine","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1072,"alias":"Caffeine anhydrous, 1,3,7-trimethylxanthine, Coffee, Pre-workout","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Drive","mid":"Muscle","lt":"Cognition","lb":"Energy"},"dots":[]},"canva":false,"primary":"Drive","roles":["Drive","Muscle","Cognition","Energy","Fat"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"3-6 mg/kg","freq":"60 min pre-exercise","cycle":"","route":"Oral, Buccal","half":"","use":"ISSN: 3-6 mg/kg improves endurance, power and focus. Adult ceiling 400 mg/day","conf":"reported"},"desc":{},"syn":[],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"ISSN: 3-6 mg/kg improves endurance, power and focus. Adult ceiling 400 mg/day","kw":["Sport and Performance","Caffeine anhydrous","1,3,7-trimethylxanthine","Coffee","Pre-workout"],"whoNot":[{"t":"People using pure caffeine powder","why":"A teaspoon can hold a lethal dose; FDA warns after deaths.","conf":"verified"},{"t":"People on fluvoxamine or ciprofloxacin","why":"These drugs block caffeine breakdown and multiply its levels.","conf":"reported"},{"t":"People on lithium","why":"Caffeine changes lithium excretion; stopping caffeine can raise lithium.","conf":"reported"}],"kind":"supp","supp":{"cat":"Sport and Performance","does":"Adenosine receptor blocker that raises alertness and lowers perceived effort. Taken about an hour before exercise it reliably improves endurance and, less consistently, strength and power. Dose by body weight, and count all sources.","benefits":"Caffeine reliably improves aerobic endurance (moderate to large effect) and gives small to moderate gains in muscular endurance, strength, sprint and power, in trained and untrained people (ISSN 2021). It improves attention and vigilance and helps performance under sleep loss. Fat-loss effects are small and fade with habitual use.","ev":"Strong","evwhy":"ISSN 2021 position stand (Guest et al.); IOC 2018 consensus lists caffeine among supplements with good performance evidence","warn":["Very high doses (around 9 mg/kg) cause frequent side effects with no added benefit","Insomnia, anxiety, palpitations and GI upset; avoid within 6-8 h of sleep","Pregnancy: cap total at 200 mg/day (EFSA, ACOG); supplements on top of coffee easily exceed it"],"buy":["Pre-measured 100 or 200 mg tablets; never measure powder by spoon","Check total mg per serving on pre-workouts and energy drinks"],"dn":"","appr":"FDA-approved as: Caffeine citrate oral solution and injection, Rx, apnoea of prematurity; caffeine also OTC alertness monograph","routes":[{"r":"Oral","note":"Capsules or coffee; capsules give a known dose, coffee varies 60-200+ mg per cup"},{"r":"Buccal","note":"Gum absorbs faster, so shorter lead time"}]}},{"slug":"s-beta-alanine","sid":"beta-alanine","name":"Beta-Alanine","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1073,"alias":"Beta alanine, β-alanine, Carnosine precursor","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Muscle","mid":"Energy","lt":"Energy","lb":"Energy"},"dots":[]},"canva":false,"primary":"Muscle","roles":["Muscle","Energy"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"4-6 g/day","freq":"Split, 2-4 doses","cycle":"","route":"Oral","half":"","use":"Raises muscle carnosine; improves 1-4 minute high-intensity efforts after 2-4 weeks loading","conf":"reported"},"desc":{},"syn":[],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Raises muscle carnosine; improves 1-4 minute high-intensity efforts after 2-4 weeks loading","kw":["Sport and Performance","Beta alanine","β-alanine","Carnosine precursor"],"whoNot":[{"t":"People relying on taurine stores","why":"Beta-alanine competes with taurine for uptake into muscle.","conf":"inferred"}],"kind":"supp","supp":{"cat":"Sport and Performance","does":"Amino acid that raises muscle carnosine, a buffer against the acid that builds up in hard efforts. After 2-4 weeks of daily loading it improves high-intensity work lasting about 1-4 minutes. Harmless tingling is the main side effect.","benefits":"Daily use raises muscle carnosine and improves high-intensity exercise lasting about 1-4 minutes, such as rowing, 400-1,500 m running, swimming and repeated sprints (ISSN 2015). Effects are small; benefit for efforts over 25 minutes is unclear. It does not build muscle or strength directly.","ev":"Strong","evwhy":"ISSN 2015 position stand; meta-analysis of 40 studies shows small gains for 0.5-10 min efforts; IOC 2018 lists it","warn":["Paresthesia (tingling of face, neck, hands) within 15-30 min of larger doses; harmless, eased by split or sustained-release dosing","May lower muscle taurine in theory (shared transporter); not shown at normal doses","Under 18: AAP discourages performance supplements"],"buy":["Check total grams per day you will actually take, including pre-workouts","NSF Certified for Sport or Informed Sport for tested athletes"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Timing around training does not matter; daily total does"}]}},{"slug":"s-sodium-bicarbonate","sid":"sodium-bicarbonate","name":"Sodium Bicarbonate","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1074,"alias":"Baking soda, Sodium hydrogen carbonate, NaHCO3, Bicarb","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Muscle","mid":"Energy","lt":"Energy","lb":"Energy"},"dots":[]},"canva":false,"primary":"Muscle","roles":["Muscle","Energy"],"reported":[],"fda":true,"fdaFill":true,"depth":"reported","short":false,"status":"","dose":{"dose":"0.2-0.3 g/kg","freq":"60-180 min pre","cycle":"","route":"Oral","half":"","use":"Blood buffer: improves 30 s-12 min all-out efforts. 0.2-0.3 g/kg about 1-3 h before","conf":"reported"},"desc":{},"syn":[],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"Blood buffer: improves 30 s-12 min all-out efforts. 0.2-0.3 g/kg about 1-3 h before","kw":["Sport and Performance","Baking soda","Sodium hydrogen carbonate","NaHCO3","Bicarb"],"whoNot":[{"t":"People on low-sodium diets or with heart failure","why":"A typical sports dose carries several grams of sodium.","conf":"reported"},{"t":"People taking it after a big meal","why":"Gas from baking soda in a full stomach has ruptured stomachs.","conf":"reported"},{"t":"People taking calcium supplements","why":"Alkali plus calcium can cause milk-alkali syndrome with kidney injury.","conf":"reported"}],"kind":"supp","supp":{"cat":"Sport and Performance","does":"Baking soda taken before exercise raises blood bicarbonate, helping muscles clear acid during very hard efforts. Improves performance in high-intensity bouts of about 30 seconds to 12 minutes. Stomach upset and a large sodium load are the trade-offs.","benefits":"Improves muscular endurance and high-intensity performance in efforts of roughly 30 seconds to 12 minutes, including repeated sprints and combat sports (ISSN 2021). Effects are small to moderate and vary between people. It does not help strength or long steady endurance.","ev":"Strong","evwhy":"ISSN 2021 position stand (Grgic et al.); IOC 2018 lists it with good evidence; individual response varies","warn":["GI distress (bloating, nausea, diarrhoea) is common and can wipe out the benefit","Huge sodium load: avoid with hypertension, heart failure, kidney disease or sodium-restricted diets","Very high doses can cause metabolic alkalosis"],"buy":["Pharmaceutical or food-grade sodium bicarbonate; weigh doses by body weight","NSF Certified for Sport or Informed Sport for tested athletes"],"dn":"","appr":"FDA-approved as: Sodium bicarbonate injection, Rx, IV, metabolic acidosis and urine alkalinisation; also OTC antacid monograph","routes":[{"r":"Oral","note":"Capsules or dissolved powder with a carbohydrate meal and fluid to reduce GI upset"}]}},{"slug":"s-lutein-and-zeaxanthin","sid":"lutein-and-zeaxanthin","name":"Lutein and Zeaxanthin","lines":null,"sub":null,"fsz":null,"origin":"supp","ref":false,"rank":1075,"alias":"AREDS2, Macular pigment, Meso-zeaxanthin, Marigold extract","seq":"","seqNote":"","sticker":{"blocks":{"wide":"Neuroprotection","mid":"Protection","lt":"Protection","lb":"Protection"},"dots":[]},"canva":false,"primary":"Neuroprotection","roles":["Neuroprotection","Protection"],"reported":[],"fda":false,"fdaFill":false,"depth":"reported","short":false,"status":"","dose":{"dose":"10 mg + 2 mg/day","freq":"Once daily with fat","cycle":"","route":"Oral","half":"","use":"AREDS2 eye formula: slows intermediate AMD to late AMD; safer than the beta-carotene version","conf":"reported"},"desc":{},"syn":[],"otl":"Supplement","tl":[],"mech":[],"tst":[],"fn":"AREDS2 eye formula: slows intermediate AMD to late AMD; safer than the beta-carotene version","kw":["Eye Health","AREDS2","Macular pigment","Meso-zeaxanthin","Marigold extract"],"whoNot":[{"t":"Smokers on AREDS-type formulas","why":"Beta-carotene raises lung cancer risk.","conf":"verified"},{"t":"Current or former smokers (lutein alone)","why":"Cohort linked lutein supplements to lung cancer.","conf":"reported"}],"kind":"supp","supp":{"cat":"Eye Health","does":"Yellow carotenoids concentrated in the macula, where they filter blue light and quench oxidation. In the AREDS2 formula they slow progression from intermediate to late age-related macular degeneration. They do not prevent AMD in healthy eyes.","benefits":"In people with intermediate AMD (or late AMD in one eye), the AREDS2 formula lowers the risk of progressing to late AMD; swapping beta-carotene for lutein and zeaxanthin cut progression risk 18% and at 10 years gave HR 0.85 vs beta-carotene. Beta-carotene nearly doubled lung cancer in former smokers, which is why it was removed. Supplements cannot prevent AMD in people without it, do not help early AMD, and did not prevent cataract overall.","ev":"Strong","evwhy":"AREDS2 RCT (4,203 people) and 10-year follow-up (JAMA Ophthalmol 2022); benefit limited to intermediate or late AMD","warn":["Benefit only proven with intermediate or late AMD; diagnosis by an eye doctor first","The full AREDS2 formula has zinc 80 mg, twice the UL: copper is included to prevent deficiency","High intakes can tint skin yellow (carotenodermia), harmless and reversible"],"buy":["Label should read 10 mg lutein and 2 mg zeaxanthin per daily dose, no beta-carotene","If buying a full AREDS2 product, confirm copper 2 mg is included with the zinc"],"dn":"","appr":"No FDA-approved medicine of this substance found.","routes":[{"r":"Oral","note":"Fat-soluble; take with a meal containing fat"}]}}]);
